function save(){localStorage.setItem('telurfarm-v1',JSON.stringify(db))}function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,4000)}function go(p){page=p;search='';filter='Semua';render();window.scrollTo(0,0)}function table(head,rows){return `<div class="tablewrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${head.length}" class="empty">Belum ada data yang cocok.</td></tr>`}</tbody></table></div>`}function title(t,sub,action=''){return `<div class="intro"><div><h1>${t}</h1><p>${sub}</p></div>${action}</div>`}function btn(text,fn,primary=true){return `<button class="btn ${primary?'primary':''}" onclick="${fn}">${text}</button>`}function stat(label,val,unit,foot){return `<div class="card"><div class="statlabel">${label}</div><div class="value">${val} <small>${unit}</small></div><div class="trend">${foot}</div></div>`}function tag(s){return `<span class="tag ${s==='Selesai'?'':s==='Dalam pengiriman'?'blue':'warn'}">${esc(s)}</span>`}function totalsAggregateBase(){const rows=db.production.filter(r=>r.date===selectedDate);return {eggs:rows.reduce((s,r)=>s+r.eggs,0),kg:rows.reduce((s,r)=>s+r.weight,0),feed:db.feedStart+db.feed.reduce((s,r)=>s+r.kg,0)-db.production.reduce((s,r)=>s+r.feed,0),stock:db.depots.reduce((s,r)=>s+r.stock,0)}}
