let cloudMeta={};try{cloudMeta=JSON.parse(localStorage.getItem('telurfarm-sync-v1')||'{}')}catch{}const localRecordPresent=Boolean(localStorage.getItem('telurfarm-v1'));let cloudRevision=Number.isSafeInteger(cloudMeta.revision)?cloudMeta.revision:0,cloudUser=cloudMeta.userId||'',cloudEmail='',cloudPending=Boolean(cloudMeta.pending),cloudEnabled=Boolean(cloudMeta.enabled),cloudReady=false,cloudBusy=false,cloudGeneration=0,cloudStatus='Memeriksa server…',cloudTime=cloudMeta.updatedAt||null,remoteSnapshot=null,cloudTimer=null,cloudConflict=false;
function persistSyncMeta(){cloudMeta={revision:cloudRevision,userId:cloudUser,pending:cloudPending,enabled:cloudEnabled,updatedAt:cloudTime};localStorage.setItem('telurfarm-sync-v1',JSON.stringify(cloudMeta))}
function saveCloud(){localStorage.setItem('telurfarm-v1',JSON.stringify(db));cloudGeneration++;cloudPending=true;persistSyncMeta();cloudStatus=cloudReady&&!cloudConflict?'Perubahan menunggu sinkronisasi':'Data tersimpan di perangkat';updateCloudUI();queueCloudSave()}
