function updateCloudUI(){const badge=$('#syncBadge');if(badge)badge.textContent=cloudConflict?'Konflik data':cloudBusy?'Menyimpan…':cloudReady?(cloudPending?'Belum tersinkron':'Tersinkron ✓'):'Data perangkat';if(page==='sync')renderSync()}
