async function cloudAPI(method='GET',body){const response=await fetch('/api/state',{method,credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});const content=response.headers.get('content-type')||'';if(!content.includes('application/json'))throw Object.assign(new Error('Sesi masuk perlu diperbarui. Masuk kembali dengan ChatGPT.'),{status:401});const value=await response.json();if(!response.ok)throw Object.assign(new Error(value.error||'Sinkronisasi gagal.'),{status:response.status,data:value});return value}
function acceptCloudData(state){const next=validateBackup({app:'TelurFarm',schema:1,data:state.data});localStorage.setItem('telurfarm-v1',JSON.stringify(next));db=next;resetStockCheckpoint();cloudRevision=state.revision;cloudUser=state.userId;cloudEmail=state.email;cloudTime=state.updatedAt;cloudPending=false;cloudEnabled=true;cloudReady=true;cloudConflict=false;remoteSnapshot=state;persistSyncMeta();cloudStatus='Data server dimuat. Sinkronisasi otomatis aktif.';render()}
