 cloudUser=state.userId;
 if(!state.data){cloudReady=cloudEnabled;cloudRevision=0;cloudStatus='Server belum memiliki data akun ini. Kirim data perangkat untuk mengaktifkan sinkronisasi.';if(cloudEnabled&&cloudPending)queueCloudSave();updateCloudUI();return}
 const same=JSON.stringify(db)===JSON.stringify(state.data),known=cloudMeta.userId===state.userId;
