async function activateCloud(){if(cloudBusy)return;if(!remoteSnapshot){await inspectCloud();if(!remoteSnapshot)return}if(remoteSnapshot.data){cloudStatus='Server sudah berisi data. Gunakan pilihan data server agar catatan server tidak tertimpa.';cloudConflict=true;updateCloudUI();return}if(cloudMeta.userId&&cloudMeta.userId!==remoteSnapshot.userId)return toast('Gunakan data server untuk akun saat ini terlebih dahulu.');cloudUser=remoteSnapshot.userId;cloudRevision=0;cloudEnabled=true;cloudReady=true;cloudPending=true;cloudConflict=false;persistSyncMeta();await pushCloud()}
