function useServerForm(){if(!remoteSnapshot?.data)return;$('#modal').innerHTML=`<h2>Gunakan data server?</h2><p style="margin-top:15px">Versi server ${remoteSnapshot.revision} · ${remoteSnapshot.data.orders.length} pesanan · ${remoteSnapshot.data.customers?.length||0} pelanggan.</p><div class="notice">Salinan lokal akan diganti. Perubahan lokal yang belum tersinkron tidak digabungkan otomatis. Unduh cadangan lokal untuk menyimpan perubahan tersebut.</div><div class="actions">${btn('Unduh cadangan lokal','backupData()',false)}${btn('Batal',"$('#modal').close()",false)}${btn('Gunakan data server','useServerData()')}</div>`;$('#modal').showModal()}
function useServerData(){if(!remoteSnapshot?.data)return;try{acceptCloudData(remoteSnapshot);$('#modal').close();cart={};toast('Data server digunakan. Cadangan lokal yang diunduh dapat disimpan untuk rekonsiliasi.')}catch(err){toast(err.message)}}
function renderSync(){$('#app').innerHTML=title('Sinkronisasi antar perangkat','Simpan di server dan akses dari perangkat yang memakai akun ChatGPT yang sama.')+`<div class="sync-message"><strong>${esc(cloudStatus)}</strong><p>${cloudEmail?'Akun: '+esc(cloudEmail):'Masuk melalui ChatGPT diperlukan untuk data server.'}</p></div><div class="sync-details">${stat('Versi data server',cloudRevision,'','Diperiksa sebelum setiap penyimpanan')}${stat('Perubahan lokal',cloudPending?'Menunggu':'Tidak ada','','Salinan lokal tetap tersedia')}${stat('Sinkronisasi',cloudReady&&cloudEnabled?'Aktif':'Belum aktif','',cloudTime?'Terakhir: '+new Date(cloudTime).toLocaleString('id-ID',{timeZone:'Asia/Bangkok'}):'Belum ada penyimpanan server')}</div><section class="card"><h2>Kelola salinan data</h2><p style="margin:15px 0">Data awal aplikasi adalah contoh. Perangkat lain akan memuat data server saat Anda masuk menggunakan akun yang sama. Akun kurir terpisah belum tersedia.</p><div class="actions" style="justify-content:start">${btn('Periksa server','inspectCloud()',false)}${btn('Unduh cadangan lokal','backupData()',false)}${!remoteSnapshot?.data?btn('Kirim data perangkat ke server','activateCloud()'):''}${remoteSnapshot?.data&&(cloudConflict||!cloudReady)?btn('Tinjau data server','useServerForm()'):''}${cloudReady&&cloudPending&&!cloudConflict?btn('Sinkronkan sekarang','pushCloud()'):''}</div><p class="note">Jika dua perangkat mengedit bersamaan, penyimpanan kedua dihentikan saat versi berbeda. Perubahan tidak digabungkan otomatis. Batas ukuran salinan data server: 1,5 MB.</p></section><div class="notice">Untuk sinkronisasi awal, kirim data perangkat yang berisi catatan utama. Pada perangkat lain, gunakan data server. Konfigurasi lokasi depo dan radius ikut tersimpan.</div>`}
