function periodCost(data,from,to){if(!validDate(from)||!validDate(to)||from>to)throw Error('Periode tidak valid.');const rows=data.production.filter(r=>r.date>=from&&r.date<=to),expenses=data.expenses.filter(r=>r.status==='Aktif'&&r.date>=from&&r.date<=to),rates=data.feedRates.filter(r=>r.status==='Aktif').slice().sort((a,b)=>a.date.localeCompare(b.date));let feedCost=0,missing=[];for(const row of rows){const rate=rates.filter(r=>r.date<=row.date).at(-1);if(row.feed>0&&!rate)missing.push(row.date+' · '+row.house);else if(rate)feedCost+=row.feed*rate.price}const productionExpenses=expenses.filter(r=>r.scope==='Produksi').reduce((s,r)=>s+r.amount,0),distributionExpenses=expenses.filter(r=>r.scope==='Distribusi').reduce((s,r)=>s+r.amount,0),kg=Number(rows.reduce((s,r)=>s+r.weight,0).toFixed(6)),eggs=rows.reduce((s,r)=>s+r.eggs,0),total=feedCost+productionExpenses;return {rows,expenses,kg,eggs,feedKg:rows.reduce((s,r)=>s+r.feed,0),feedCost,productionExpenses,distributionExpenses,total,missing,hppKg:missing.length||kg<=0?null:total/kg,hppEgg:missing.length||eggs<=0?null:total/eggs}}
function rp(value){return value===null?'Belum tersedia':money(Math.round(value))}
function enhanceCosts(){enhanceCloud();if(page==='costs')renderCosts()}
function renderCosts(){let report;try{report=periodCost(db,costFrom,costTo)}catch(err){$('#app').innerHTML=title('Biaya & HPP telur','Pilih periode biaya dan produksi.')+costFilters()+`<div class="notice">${esc(err.message)}</div>`;return}const marginRows=['Perorangan','Wholesale','Hotel/Resort'].flatMap(category=>products.map((p,i)=>`<tr><td>${category}</td><td>${p.name}</td><td>${money(db.priceList[category][i].kg)}</td><td>${report.hppKg===null?'—':rp(db.priceList[category][i].kg-report.hppKg)}</td><td>${money(db.priceList[category][i].butir)}</td><td>${report.hppEgg===null?'—':rp(db.priceList[category][i].butir-report.hppEgg)}</td></tr>`));$('#app').innerHTML=title('Biaya & HPP telur','Estimasi biaya produksi dari konsumsi pakan dan biaya yang dicatat.',btn('+ Catat biaya','expenseForm()'))+costFilters()+`<div class="stats">${stat('Produksi telur baik',num(report.kg),'kg',num(report.eggs)+' butir · '+report.rows.length+' catatan kandang')}${stat('Biaya produksi tercatat',rp(report.total),'',report.missing.length?'Belum lengkap: harga pakan belum tersedia':'Konsumsi pakan + biaya produksi')}${stat('Estimasi HPP / kg',rp(report.hppKg),'','Rata-rata produksi periode terpilih')}${stat('Estimasi HPP / butir',rp(report.hppEgg),'','Dibagi jumlah telur baik')}</div>${report.missing.length?`<div class="notice"><strong>Lengkapi harga pakan sebelum HPP dihitung.</strong><br>${report.missing.map(esc).join('<br>')}</div>`:''}<div class="grid"><section class="card"><h2>Komponen biaya periode</h2><div class="cartline"><span>Konsumsi pakan</span><strong>${num(report.feedKg)} kg</strong></div><div class="cartline"><span>Biaya pakan terhitung</span><strong>${rp(report.feedCost)}</strong></div><div class="cartline"><span>Biaya produksi lainnya</span><strong>${rp(report.productionExpenses)}</strong></div><div class="cartline"><span>Biaya distribusi (terpisah)</span><strong>${rp(report.distributionExpenses)}</strong></div><p class="note">Pembelian pakan tidak dijumlahkan lagi ke HPP: hanya pakan yang dikonsumsi yang dibebankan, menggunakan harga berlaku pada tanggal produksi.</p></section><section class="card"><div class="cardhead"><h2>Harga pakan berlaku</h2><button class="textbtn" onclick="feedRateForm()">+ Tambah harga</button></div>${table(['BERLAKU MULAI','Rp / KG','STATUS','AKSI'],db.feedRates.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td>${r.date}</td><td>${money(r.price)}</td><td>${tag(r.status)}</td><td>${r.status==='Aktif'?`<button class="textbtn" onclick="feedRateForm('${r.id}')">Edit</button>`:'—'}</td></tr>`))}<p class="note">Catat harga pakan produksi, bukan harga telur. Perubahan harga berlaku sejak tanggal yang Anda pilih.</p></section></div><section class="card bottom"><div class="cardhead"><h2>Biaya operasional periode</h2><button class="textbtn" onclick="exportCosts()">↓ Ekspor biaya CSV</button></div>${table(['TANGGAL','KATEGORI','ALOKASI','KETERANGAN','JUMLAH','STATUS','AKSI'],db.expenses.filter(r=>r.date>=costFrom&&r.date<=costTo).slice().sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td>${r.date}</td><td>${esc(r.category)}</td><td>${r.scope}</td><td>${esc(r.note)}</td><td>${money(r.amount)}</td><td>${tag(r.status)}</td><td>${r.status==='Aktif'?`<button class="textbtn" onclick="expenseForm('${r.id}')">Edit</button><button class="textbtn" onclick="cancelExpenseForm('${r.id}')">Batalkan</button>`:'—'}</td></tr>`))}</section><section class="card bottom"><h2 style="margin-bottom:15px">Selisih harga jual terhadap estimasi HPP</h2>${table(['PEMBELI','VARIAN','HARGA / KG','SELISIH / KG','HARGA / BUTIR','SELISIH / BUTIR'],marginRows)}<p class="note">Menggunakan harga jual saat ini dan HPP rata-rata semua kandang/varian. Selisih ini belum dikurangi biaya distribusi dan biaya yang belum dicatat; bukan laba bersih.</p></section>`}
function costFilters(){return `<div class="filters"><label>Dari <input aria-label="Awal periode HPP" type="date" value="${costFrom}" onchange="costFrom=this.value;renderCosts()"></label><label>Sampai <input aria-label="Akhir periode HPP" type="date" value="${costTo}" onchange="costTo=this.value;renderCosts()"></label></div>`}
function expenseForm(id=''){const r=db.expenses.find(r=>r.id===id)||{date:costTo,category:'Tenaga kerja',scope:'Produksi',note:'',amount:''};$('#modal').innerHTML=`<h2>${id?'Edit':'Catat'} biaya operasional</h2><form onsubmit="saveExpense(event,'${id}')">${field('Tanggal biaya','date','date',`value="${r.date}"`)}<label>Kategori biaya</label><select name="category">${expenseCategories.map(c=>`<option ${c===r.category?'selected':''}>${c}</option>`).join('')}</select><label>Alokasi biaya</label><select name="scope"><option ${r.scope==='Produksi'?'selected':''}>Produksi</option><option ${r.scope==='Distribusi'?'selected':''}>Distribusi</option></select>${field('Keterangan','note','text',`maxlength="300" value="${esc(r.note)}"`)}${field('Jumlah biaya (Rp)','amount','number',`min="1" max="1000000000000" step="1" value="${r.amount}"`)}<div class="notice">Biaya produksi masuk ke estimasi HPP. Biaya distribusi dilaporkan terpisah. Pembelian pakan dicatat melalui menu Pakan dan tidak dicatat lagi di sini.</div><div class="actions"><button type="button" class="btn" onclick="$('#modal').close()">Batal</button><button class="btn primary">Simpan biaya</button></div></form>`;$('#modal').showModal()}
function saveExpense(e,id){e.preventDefault();const r=Object.fromEntries(new FormData(e.target));r.amount=Number(r.amount);if(!validDate(r.date)||!expenseCategories.includes(r.category)||!['Produksi','Distribusi'].includes(r.scope)||!r.note.trim()||r.note.length>300||!Number.isSafeInteger(r.amount)||r.amount<=0||r.amount>1000000000000)return toast('Tanggal, kategori, keterangan, atau jumlah biaya tidak valid.');const existing=db.expenses.find(r=>r.id===id);if(id&&(!existing||existing.status!=='Aktif'))return toast('Biaya tidak tersedia untuk diedit.');if(existing)Object.assign(existing,r);else db.expenses.unshift({...r,id:'EXP-'+crypto.randomUUID().replaceAll('-','').toUpperCase(),status:'Aktif'});audit((id?'Edit':'Catat')+' biaya '+r.category+' '+money(r.amount));save();$('#modal').close();render();toast('Biaya disimpan. Estimasi HPP diperbarui.')}
function cancelExpenseForm(id){const r=db.expenses.find(r=>r.id===id);if(!r||r.status!=='Aktif')return;$('#modal').innerHTML=`<h2>Batalkan catatan biaya?</h2><p style="margin-top:15px">${esc(r.note)} · ${money(r.amount)}</p><div class="notice">Catatan tetap ada, tetapi dikeluarkan dari perhitungan biaya dan HPP. Tindakan ini tidak membatalkan transaksi bank.</div><div class="actions">${btn('Kembali',"$('#modal').close()",false)}${btn('Ya, batalkan',`cancelExpense('${id}')`)}</div>`;$('#modal').showModal()}
function cancelExpense(id){const r=db.expenses.find(r=>r.id===id);if(!r||r.status!=='Aktif')return;r.status='Dibatalkan';audit('Pembatalan biaya '+id);save();$('#modal').close();render();toast('Catatan biaya dibatalkan.')}
function feedRateForm(id=''){const r=db.feedRates.find(r=>r.id===id)||{date:costFrom,price:''};$('#modal').innerHTML=`<h2>Harga pakan produksi</h2><form onsubmit="saveFeedRate(event,'${id}')">${field('Berlaku mulai tanggal','date','date',`value="${r.date}"`)}${field('Harga pakan (Rp / kg)','price','number',`min="1" max="1000000" step="1" value="${r.price}"`)}<div class="notice">Konsumsi pakan memakai harga terakhir yang berlaku pada tanggal produksi. Koreksi harga akan menghitung ulang estimasi HPP historis sejak tanggal berlaku. Harga awal tidak diasumsikan.</div><div class="actions"><button type="button" class="btn" onclick="$('#modal').close()">Batal</button><button class="btn primary">Simpan harga</button></div></form>`;$('#modal').showModal()}
function saveFeedRate(e,id){e.preventDefault();const r=Object.fromEntries(new FormData(e.target));r.price=Number(r.price);if(!validDate(r.date)||!Number.isSafeInteger(r.price)||r.price<=0||r.price>1000000)return toast('Tanggal atau harga pakan tidak valid.');if(db.feedRates.some(x=>x.id!==id&&x.status==='Aktif'&&x.date===r.date))return toast('Harga pada tanggal tersebut sudah ada. Edit catatan yang tersedia.');const existing=db.feedRates.find(x=>x.id===id);if(id&&(!existing||existing.status!=='Aktif'))return toast('Harga tidak tersedia untuk diedit.');if(existing)Object.assign(existing,r);else db.feedRates.push({...r,id:'RATE-'+crypto.randomUUID().replaceAll('-','').toUpperCase(),status:'Aktif'});audit('Harga pakan mulai '+r.date+': '+money(r.price)+'/kg');save();$('#modal').close();render();toast('Harga pakan disimpan. Estimasi HPP dihitung ulang.')}
function exportCosts(){const rows=[['ID','Tanggal','Kategori','Alokasi','Keterangan','Jumlah Rp','Status'],...db.expenses.filter(r=>r.date>=costFrom&&r.date<=costTo).map(r=>[r.id,r.date,r.category,r.scope,r.note,r.amount,r.status])],csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='PamanKu-Biaya-'+costFrom+'-'+costTo+'.csv';a.click();URL.revokeObjectURL(a.href)}
function validateCosts(data){const categories=['Tenaga kerja','Listrik & air','Kesehatan ayam','Perawatan kandang','Kemasan','Transportasi','Penyusutan','Lainnya'];if(data.expenses!==undefined){if(!Array.isArray(data.expenses)||data.expenses.length>100000)throw Error('Data biaya tidak valid.');const ids=new Set();for(const r of data.expenses){if(typeof r.id!=='string'||!/^EXP-(?:[A-F0-9]{8}|[A-F0-9]{32})$/.test(r.id)||ids.has(r.id)||!validDate(r.date)||!categories.includes(r.category)||!['Produksi','Distribusi'].includes(r.scope)||typeof r.note!=='string'||!r.note.trim()||r.note.length>300||!Number.isSafeInteger(r.amount)||r.amount<=0||r.amount>1000000000000||!['Aktif','Dibatalkan'].includes(r.status))throw Error('Isi catatan biaya tidak valid.');ids.add(r.id)}}if(data.feedRates!==undefined){if(!Array.isArray(data.feedRates)||data.feedRates.length>10000)throw Error('Harga pakan tidak valid.');const ids=new Set(),dates=new Set();for(const r of data.feedRates){if(typeof r.id!=='string'||!/^RATE-(?:[A-F0-9]{8}|[A-F0-9]{32})$/.test(r.id)||ids.has(r.id)||!validDate(r.date)||!Number.isSafeInteger(r.price)||r.price<=0||r.price>1000000||!['Aktif','Dibatalkan'].includes(r.status)||(r.status==='Aktif'&&dates.has(r.date)))throw Error('Isi harga pakan tidak valid.');ids.add(r.id);if(r.status==='Aktif')dates.add(r.date)}}}
function migrateStockControl(data){data.stockJournal??=[]}
function depotBalances(){return db.depots.map(d=>({name:d.name,kg:d.stock,eggs:d.eggs}))}
let stockCheckpoint=depotBalances(),stockContext=null,stockDepotFilter='Semua';function resetStockCheckpoint(){stockCheckpoint=depotBalances();stockContext=null}
function save(){const added=[];for(const d of db.depots){const before=stockCheckpoint.find(x=>x.name===d.name);if(!before)continue;const deltaKg=Number((d.stock-before.kg).toFixed(6)),deltaEggs=d.eggs-before.eggs;if(Math.abs(deltaKg)>0.0000001||deltaEggs!==0){const context=stockContext||stockAuditContext();const entry={id:'MOV-'+crypto.randomUUID().replaceAll('-','').toUpperCase(),time:new Date().toISOString(),depot:d.name,type:context.type,note:String(context.note).slice(0,300),beforeKg:before.kg,afterKg:d.stock,beforeEggs:before.eggs,afterEggs:d.eggs,deltaKg,deltaEggs};db.stockJournal.unshift(entry);added.push(entry.id)}}try{saveCloud();resetStockCheckpoint()}catch(err){db.stockJournal=db.stockJournal.filter(e=>!added.includes(e.id));throw err}}
function enhanceStock(){enhanceCosts();if(page==='inventory'){const section=document.createElement('section');section.className='card bottom';section.innerHTML=`<div class="cardhead"><h2>Koreksi, telur rusak & kehilangan</h2>${btn('+ Catat perubahan','stockChangeForm()')}</div><p>Saldo tersedia tidak termasuk telur yang sudah dialokasikan ke pesanan. Catat berat dan butir sesuai hasil hitung fisik.</p><div class="filters bottom"><select aria-label="Filter jurnal depo" onchange="stockDepotFilter=this.value;renderStockJournal()">${['Semua',...db.depots.map(d=>d.name)].map(d=>`<option ${stockDepotFilter===d?'selected':''}>${esc(d)}</option>`).join('')}</select><button class="btn" onclick="exportStockJournal()">↓ Ekspor jurnal CSV</button></div><div id="stockJournalTable"></div><p class="note">Jurnal mencatat perubahan sejak v1.8, termasuk produksi, transfer, alokasi pesanan, dan koreksi. Riwayat sebelum pembaruan tidak dibuat ulang.</p>`;$('#app').append(section);renderStockJournal()}}
function renderStockJournal(){const rows=db.stockJournal.filter(r=>stockDepotFilter==='Semua'||r.depot===stockDepotFilter);$('#stockJournalTable').innerHTML=table(['WAKTU','DEPO','PERUBAHAN','KG','BUTIR','SALDO KG / BUTIR','CATATAN'],rows.slice(0,100).map(r=>`<tr><td>${esc(new Date(r.time).toLocaleString('id-ID',{timeZone:'Asia/Bangkok'}))}</td><td>${esc(r.depot)}</td><td>${esc(r.type)}</td><td>${r.deltaKg>0?'+':''}${num(r.deltaKg)}</td><td>${r.deltaEggs>0?'+':''}${num(r.deltaEggs)}</td><td>${num(r.afterKg)} kg / ${num(r.afterEggs)}</td><td>${esc(r.note)}</td></tr>`))+`<p class="note">${rows.length} catatan · maksimal 100 ditampilkan; ekspor mencakup seluruh catatan hasil filter.</p>`}
function stockChangeAggregateForm(){$('#modal').innerHTML=`<h2>Catat perubahan stok</h2><form onsubmit="saveStockChange(event)">${sel('Depo','depot',db.depots.map(d=>d.name))}${sel('Jenis perubahan','type',['Telur rusak','Kehilangan','Koreksi tambah','Koreksi kurang'])}${field('Berat (kg)','kg','number','min="0.001" step="0.001"')}${field('Jumlah (butir)','eggs','number','min="1" step="1"')}${field('Alasan / catatan','note','text','maxlength="300"')}<div class="notice">Telur rusak, kehilangan, dan koreksi kurang mengurangi stok tersedia. Koreksi tambah menambah stok. Catatan ini tidak otomatis menjadi biaya pada laporan HPP.</div><div class="actions"><button type="button" class="btn" onclick="$('#modal').close()">Batal</button><button class="btn primary">Simpan perubahan</button></div></form>`;$('#modal').showModal()}
function saveStockChangeAggregateBase(e){e.preventDefault();const r=Object.fromEntries(new FormData(e.target)),d=db.depots.find(d=>d.name===r.depot),kg=Number(r.kg),eggs=Number(r.eggs);if(!d||!['Telur rusak','Kehilangan','Koreksi tambah','Koreksi kurang'].includes(r.type)||!Number.isFinite(kg)||kg<=0||!Number.isSafeInteger(eggs)||eggs<=0||!r.note.trim()||r.note.length>300)return toast('Berat, jumlah butir, atau catatan tidak valid.');const direction=r.type==='Koreksi tambah'?1:-1;if(direction<0&&(kg>d.stock+0.0000001||eggs>d.eggs))return toast('Jumlah melebihi stok tersedia. Telur yang dialokasikan ke pesanan tidak dapat dikurangi di sini.');d.stock=Number(Math.max(0,d.stock+direction*kg).toFixed(6));d.eggs+=direction*eggs;stockContext={type:r.type,note:r.note};audit(r.type+' '+d.name+': '+num(kg)+' kg / '+eggs+' butir');save();$('#modal').close();render();toast('Perubahan stok dicatat pada jurnal.')}
function packingItems(o){return o.items||[{name:o.product,unit:'kg',quantity:o.kg}]}
function packingAggregateForm(id){const o=db.orders.find(o=>o.id===id);if(!o||o.status!=='Diproses')return;const rows=packingItems(o);$('#modal').innerHTML=`<h2>Hitung & timbang ${esc(id)}</h2><p>Pastikan jumlah pada satuan yang dibeli sama dengan pesanan. Berat untuk pembelian butir dan jumlah butir untuk pembelian kg diisi dari pengukuran aktual.</p><form onsubmit="savePacking(event,'${id}')">${rows.map((r,i)=>{const previous=o.packing?.items[i];return `<h3 style="font-size:14px;margin:20px 0 5px">${esc(r.name)} · ${num(r.quantity)} ${esc(r.unit)}</h3><div class="formrow"><div>${field('Berat aktual (kg)','kg'+i,'number',`min="0.000001" step="any" ${r.unit==='kg'?`readonly value="${r.quantity}"`:`value="${previous?.kg||''}"`}`)}</div><div>${field('Jumlah aktual (butir)','eggs'+i,'number',`min="1" step="1" ${r.unit==='butir'?`readonly value="${r.quantity}"`:`value="${previous?.eggs||''}"`}`)}</div></div>`}).join('')}${field('Catatan pemeriksaan','note','text',`maxlength="300" value="${esc(o.packing?.note||'')}"`)}<div class="notice">Pengukuran memperbarui alokasi stok, bukan harga atau satuan yang ditagihkan. Jika jumlah pada satuan yang dibeli berubah, pesanan perlu dikoreksi melalui pembatalan/pemesanan ulang sesuai status pembayaran.</div><div class="actions"><button type="button" class="btn" onclick="detail('${id}')">Kembali</button><button class="btn primary">Simpan hasil ukur</button></div></form>`;if(!$('#modal').open)$('#modal').showModal()}
function savePackingAggregateBase(e,id){e.preventDefault();const o=db.orders.find(o=>o.id===id),r=Object.fromEntries(new FormData(e.target));if(!o||o.status!=='Diproses')return toast('Pengukuran hanya bisa diubah sebelum pengiriman.');if(!r.note.trim()||r.note.length>300)return toast('Isi catatan pemeriksaan.');const expected=packingItems(o),items=expected.map((row,i)=>({name:row.name,unit:row.unit,quantity:row.quantity,kg:Number(r['kg'+i]),eggs:Number(r['eggs'+i])}));if(items.some(i=>!Number.isFinite(i.kg)||i.kg<=0||!Number.isSafeInteger(i.eggs)||i.eggs<=0||(i.unit==='kg'&&Math.abs(i.kg-i.quantity)>0.0000001)||(i.unit==='butir'&&i.eggs!==i.quantity)))return toast('Pengukuran tidak valid atau tidak sesuai jumlah pada satuan pesanan.');const kg=Number(items.reduce((s,i)=>s+i.kg,0).toFixed(6)),eggs=items.reduce((s,i)=>s+i.eggs,0),d=db.depots.find(d=>d.name===o.depot),poolKg=d.stock+o.kg,poolEggs=d.eggs+o.stockEggs;if(kg>poolKg+0.0000001||eggs>poolEggs)return toast('Stok depo tidak cukup untuk hasil ukur. Alokasi lama dipertahankan.');d.stock=Number(Math.max(0,poolKg-kg).toFixed(6));d.eggs=poolEggs-eggs;o.kg=kg;o.stockEggs=eggs;o.packing={items,note:r.note,time:new Date().toISOString()};stockContext={type:'Pengukuran pesanan',note:id+' · '+r.note};deliveryEvent(o,'Hitung & timbang',num(kg)+' kg / '+eggs+' butir');save();$('#modal').close();render();toast('Hasil ukur disimpan. Alokasi stok diperbarui; nilai invoice tetap.')}
function detailStockBase(id){detailDeliveryBase(id);const o=db.orders.find(o=>o.id===id);if(!o)return;$('#modal').innerHTML+=`<div class="notice"><strong>${o.packing?'Hasil ukur aktual tercatat':'Pengukuran aktual belum tercatat'}</strong><br>Alokasi stok: ${num(o.kg)} kg / ${num(o.stockEggs)} butir${o.packing?`<br>${esc(o.packing.note)}<br>${esc(new Date(o.packing.time).toLocaleString('id-ID',{timeZone:'Asia/Bangkok'}))}`:''}</div>${o.status==='Diproses'?`<div class="actions">${btn('Hitung & timbang',`packingForm('${id}')`)}</div>`:''}`}
function advance(id){const o=db.orders.find(o=>o.id===id);if(o?.status==='Diproses'&&!o.packing)return toast('Catat hasil hitung dan timbang aktual sebelum pengiriman.');return advancePackedBase(id)}
function exportStockJournal(){const rows=[['ID','Waktu','Depo','Jenis','Perubahan kg','Perubahan butir','Saldo kg','Saldo butir','Catatan'],...db.stockJournal.filter(r=>stockDepotFilter==='Semua'||r.depot===stockDepotFilter).map(r=>[r.id,r.time,r.depot,r.type,r.deltaKg,r.deltaEggs,r.afterKg,r.afterEggs,r.note])],csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='PamanKu-Jurnal-Stok.csv';a.click();URL.revokeObjectURL(a.href)}
function validateStockControl(data){if(data.stockJournal!==undefined){if(!Array.isArray(data.stockJournal)||data.stockJournal.length>100000)throw Error('Jurnal stok tidak valid.');const ids=new Set();for(const r of data.stockJournal){if(typeof r.id!=='string'||!/^MOV-(?:[A-F0-9]{8}|[A-F0-9]{32})$/.test(r.id)||ids.has(r.id)||!Number.isFinite(Date.parse(r.time))||!data.depots.some(d=>d.name===r.depot)||typeof r.type!=='string'||r.type.length>100||typeof r.note!=='string'||r.note.length>300||![r.beforeKg,r.afterKg,r.deltaKg].every(Number.isFinite)||r.beforeKg<0||r.afterKg<0||![r.beforeEggs,r.afterEggs].every(v=>Number.isSafeInteger(v)&&v>=0)||!Number.isSafeInteger(r.deltaEggs)||Math.abs(r.afterKg-r.beforeKg-r.deltaKg)>0.000001||r.afterEggs-r.beforeEggs!==r.deltaEggs)throw Error('Isi jurnal stok tidak valid.');ids.add(r.id)}}for(const o of data.orders){if(o.packing!==undefined){const p=o.packing,expected=o.items||[{name:o.product,unit:'kg',quantity:o.kg}];if(!Array.isArray(p.items)||p.items.length!==expected.length||typeof p.note!=='string'||!p.note.trim()||p.note.length>300||!Number.isFinite(Date.parse(p.time)))throw Error('Hasil ukur pesanan tidak valid.');if(p.items.some((i,n)=>i.name!==expected[n].name||i.unit!==expected[n].unit||i.quantity!==expected[n].quantity||!Number.isFinite(i.kg)||i.kg<=0||!Number.isSafeInteger(i.eggs)||i.eggs<=0||(i.unit==='kg'&&Math.abs(i.kg-i.quantity)>0.0000001)||(i.unit==='butir'&&i.eggs!==i.quantity))||Math.abs(p.items.reduce((s,i)=>s+i.kg,0)-o.kg)>0.000001||p.items.reduce((s,i)=>s+i.eggs,0)!==o.stockEggs)throw Error('Jumlah hasil ukur tidak sesuai alokasi pesanan.')}}}
function stockAuditContext(){const note=db.audit[0]?.action||'Pembaruan saldo depo';if(note==='Simpan production')return {type:'Produksi telur',note:'Penambahan stok dari catatan produksi'};if(note==='Simpan transfer')return {type:'Transfer antar depo',note:'Perpindahan stok antar depo'};if(note.startsWith('Pesanan TF-'))return {type:'Alokasi pesanan',note};if(note.startsWith('Pembatalan TF-'))return {type:'Pengembalian pesanan',note};if(note.startsWith('Penyesuaian saldo'))return {type:'Koreksi saldo fisik',note};return {type:'Perubahan stok',note}}
function invoiceStockBase(o){return invoiceDeliveryBase(o).replace('</article>',o.packing?`<section style="margin-top:20px"><h2 style="margin-bottom:10px">Hasil hitung & timbang</h2>${table(['PRODUK','BERAT AKTUAL','BUTIR AKTUAL'],o.packing.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${num(i.kg)} kg</td><td>${num(i.eggs)} butir</td></tr>`))}<p class="note">${esc(o.packing.note)} · Harga dan satuan tagihan mengikuti pesanan.</p></section></article>`:'</article>')}
