let repeatContext=null;
function planOccurrence(plan,n){const start=new Date(plan.startDate+'T00:00:00Z');if(plan.cadence==='Bulanan'){const day=start.getUTCDate();start.setUTCDate(1);start.setUTCMonth(start.getUTCMonth()+n);const last=new Date(Date.UTC(start.getUTCFullYear(),start.getUTCMonth()+1,0));start.setUTCDate(Math.min(day,last.getUTCDate()))}else start.setUTCDate(start.getUTCDate()+n*(plan.cadence==='Mingguan'?7:1));return start.toISOString().slice(0,10)}
function nextPlanDate(plan,floor=todayLocal()){if(!plan.active)return null;const start=new Date(plan.startDate+'T00:00:00Z'),day=new Date(floor+'T00:00:00Z');let n=plan.cadence==='Bulanan'?Math.max(0,(day.getUTCFullYear()-start.getUTCFullYear())*12+day.getUTCMonth()-start.getUTCMonth()):Math.max(0,Math.floor((day-start)/(86400000*(plan.cadence==='Mingguan'?7:1))));const used=new Set(db.orders.filter(o=>o.recurringPlanId===plan.id&&o.status!=='Dibatalkan').map(o=>o.deliveryDate));for(let i=0;i<10000;i++,n++){const candidate=planOccurrence(plan,n);if(candidate>=floor&&!used.has(candidate))return candidate}return null}
function planItemsFromOrder(o){if(o.items)return o.items.map(i=>({product:Number.isInteger(i.product)?i.product:products.findIndex(p=>p.name===i.name),unit:i.unit,quantity:i.quantity}));const product=products.findIndex(p=>p.name===o.product);return product<0?[]:[{product,unit:'kg',quantity:o.kg}]}
