function renderRecurring(){$('#app').innerHTML=title('Pesanan rutin bisnis','Template untuk wholesale dan hotel/resort; setiap pesanan tetap ditinjau saat checkout.',btn('+ Buat template','planForm()'))+`<div class="stats">${stat('Template aktif',db.orderPlans.filter(p=>p.active).length,'template','Tidak membuat pesanan otomatis')}${stat('Template dijeda',db.orderPlans.filter(p=>!p.active).length,'template','Riwayat pesanan tetap tersedia')}${stat('Pesanan dari template',db.orders.filter(o=>o.recurringPlanId&&o.status!=='Dibatalkan').length,'pesanan','Jumlah pesanan aktif dan selesai')}${stat('Pelanggan bisnis',db.customers.filter(c=>c.category!=='Perorangan').length,'pelanggan','Wholesale dan hotel/resort')}</div><section class="card bottom">${table(['TEMPLATE / PELANGGAN','POLA','ISI PESANAN','BERIKUTNYA','STATUS','AKSI'],db.orderPlans.map(p=>{const c=db.customers.find(c=>c.id===p.customerId);return `<tr><td><strong>${esc(p.title)}</strong><p>${esc(c?.name||'Pelanggan tidak tersedia')}</p><p>${esc(p.depot)}</p></td><td>${esc(p.cadence)}<p>Mulai ${p.startDate}</p></td><td>${p.items.map(i=>esc(products[i.product].name)+' · '+num(i.quantity)+' '+i.unit).join('<br>')}</td><td>${nextPlanDate(p)||'—'}</td><td>${tag(p.active?'Aktif':'Dijeda')}</td><td><button class="textbtn" onclick="planForm('${p.id}')">Edit</button><button class="textbtn" onclick="togglePlan('${p.id}')">${p.active?'Jeda':'Aktifkan'}</button>${p.active?`<button class="textbtn" onclick="reviewPlan('${p.id}')">Siapkan pesanan →</button>`:''}</td></tr>`}))}</section><div class="notice">Template menyimpan jumlah dan satuan, bukan harga kontrak. Harga saat ini, stok depo, cakupan layanan, alamat, dan jadwal diperiksa kembali. Pesanan dari template yang sama pada tanggal yang sama tidak boleh dibuat dua kali, kecuali pesanan sebelumnya dibatalkan.</div>`}
function planForm(id='',sourceId=''){const existing=db.orderPlans.find(p=>p.id===id),source=db.orders.find(o=>o.id===sourceId),r=existing||{title:source?'Rutin '+source.name:'',customerId:source?.customerId||'',items:source?planItemsFromOrder(source):[],cadence:'Mingguan',startDate:todayLocal(),slot:source?.deliverySlot||'Pagi (08–12)',depot:source?.depot||db.depots[0].name,notes:source?.deliveryNotes||'',active:true},customers=db.customers.filter(c=>c.category!=='Perorangan');if(!customers.length)return toast('Tambahkan pelanggan wholesale atau hotel/resort terlebih dahulu.');$('#modal').innerHTML=`<h2>${id?'Edit':'Buat'} template rutin</h2><form onsubmit="savePlan(event,'${id}')">${field('Nama template','title','text',`maxlength="100" value="${esc(r.title)}"`)}<label>Pelanggan bisnis</label><select name="customerId">${customers.map(c=>`<option value="${c.id}" ${c.id===r.customerId?'selected':''}>${esc(c.name)} · ${esc(c.category)}</option>`).join('')}</select><div class="formrow"><div><label>Pola pengiriman</label><select name="cadence">${['Harian','Mingguan','Bulanan'].map(c=>`<option ${c===r.cadence?'selected':''}>${c}</option>`).join('')}</select></div><div>${field('Tanggal mulai','startDate','date',`min="2000-01-01" max="2100-12-31" value="${r.startDate}"`)}</div></div><label>Depo pilihan awal</label><select name="depot">${db.depots.map(d=>`<option ${d.name===r.depot?'selected':''}>${d.name}</option>`).join('')}</select><label>Slot pengiriman</label><select name="slot">${['Pagi (08–12)','Siang (12–16)','Sore (16–20)'].map(s=>`<option ${s===r.slot?'selected':''}>${s}</option>`).join('')}</select><h3 style="font-size:14px;margin:20px 0">Jumlah telur per pesanan</h3>${products.map((p,i)=>`<p>${p.name}</p><div class="formrow"><div><label>Kilogram (0 jika tidak dipakai)</label><input name="qty${i}_kg" type="number" min="0" max="100000" step="0.01" value="${r.items.find(x=>x.product===i&&x.unit==='kg')?.quantity||0}"></div><div><label>Butir (0 jika tidak dipakai)</label><input name="qty${i}_butir" type="number" min="0" max="1000000" step="1" value="${r.items.find(x=>x.product===i&&x.unit==='butir')?.quantity||0}"></div></div>`).join('')}<label>Catatan pengiriman</label><input name="notes" maxlength="300" value="${esc(r.notes)}"><div class="notice">Bulanan memakai tanggal mulai sebagai patokan. Jika tanggal tersebut tidak ada pada suatu bulan, aplikasi memakai hari terakhir bulan itu. Pesanan tetap dibuat melalui checkout.</div><div class="actions"><button type="button" class="btn" onclick="$('#modal').close()">Batal</button><button class="btn primary">Simpan template</button></div></form>`;if(!$('#modal').open)$('#modal').showModal()}
function savePlan(e,id){e.preventDefault();const r=Object.fromEntries(new FormData(e.target)),c=db.customers.find(c=>c.id===r.customerId),items=[];for(let product=0;product<3;product++)for(const unit of ['kg','butir']){const quantity=Number(r['qty'+product+'_'+unit]);if(!Number.isFinite(quantity)||quantity<0||(unit==='butir'&&!Number.isSafeInteger(quantity))||(unit==='kg'&&Math.abs(quantity*100-Math.round(quantity*100))>0.000001)||quantity>(unit==='kg'?100000:1000000))return toast('Jumlah kg atau butir tidak valid.');if(quantity>0)items.push({product,unit,quantity})}if(!r.title.trim()||r.title.length>100||!c||c.category==='Perorangan'||!validDate(r.startDate)||r.startDate<'2000-01-01'||r.startDate>'2100-12-31'||!['Harian','Mingguan','Bulanan'].includes(r.cadence)||!['Pagi (08–12)','Siang (12–16)','Sore (16–20)'].includes(r.slot)||!db.depots.some(d=>d.name===r.depot)||r.notes.length>300||!items.length)return toast('Lengkapi nama, pelanggan bisnis, jadwal, dan minimal satu jumlah telur.');const existing=db.orderPlans.find(p=>p.id===id);if(id&&!existing)return toast('Template tidak ditemukan.');const next={title:r.title.trim(),customerId:r.customerId,items,cadence:r.cadence,startDate:r.startDate,slot:r.slot,depot:r.depot,notes:r.notes};if(existing)Object.assign(existing,next);else db.orderPlans.push({...next,id:'PLAN-'+crypto.randomUUID().replaceAll('-','').toUpperCase(),active:true});audit((id?'Edit':'Buat')+' template pesanan '+next.title);save();$('#modal').close();render();toast('Template disimpan. Pesanan lama tetap dipertahankan.')}
function togglePlan(id){const p=db.orderPlans.find(p=>p.id===id);if(!p)return;p.active=!p.active;audit((p.active?'Aktifkan':'Jeda')+' template '+p.title);save();render();toast(p.active?'Template diaktifkan.':'Template dijeda; pesanan yang sudah dibuat tetap berjalan.')}
function reviewPlan(id){const p=db.orderPlans.find(p=>p.id===id),c=p&&db.customers.find(c=>c.id===p.customerId);if(!p?.active||!c||c.category==='Perorangan')return toast('Template aktif dan pelanggan bisnis diperlukan.');const date=nextPlanDate(p);if(!date)return toast('Jadwal berikutnya tidak tersedia.');reviewRepeat({planId:id,customerId:c.id,items:p.items,deliveryDate:date,slot:p.slot,depot:p.depot,notes:p.notes,title:p.title})}
function repeatOrder(id){const o=db.orders.find(o=>o.id===id);if(!o)return;const items=planItemsFromOrder(o);if(!items.length||items.some(i=>i.product<0))return toast('Rincian varian pesanan lama tidak tersedia. Pilih telur melalui toko.');reviewRepeat({sourceOrderId:id,customerId:o.customerId,items,deliveryDate:todayLocal(),slot:o.deliverySlot||'Pagi (08–12)',depot:o.depot,notes:o.deliveryNotes||'',title:'Pesan ulang '+id})}
let pendingRepeat=null;function reviewRepeat(proposal){const c=db.customers.find(c=>c.id===proposal.customerId);if(!c)return toast('Data pelanggan tidak ditemukan.');pendingRepeat=structuredClone(proposal);const amount=proposal.items.reduce((s,i)=>s+Math.round(db.priceList[c.category][i.product][i.unit]*i.quantity),0);$('#modal').innerHTML=`<h2>${esc(proposal.title)}</h2><p style="margin-top:15px">${esc(c.name)} · ${esc(c.category)}<br>${proposal.deliveryDate} · ${esc(proposal.slot)}</p><div class="notice">${proposal.items.map(i=>esc(products[i.product].name)+' · '+num(i.quantity)+' '+i.unit).join('<br>')}<br><strong>Estimasi harga saat ini: ${money(amount)}</strong></div><p>${cartEntries().length?'Keranjang yang ada akan diganti setelah Anda menekan tombol berikut.':'Belum ada pesanan dibuat atau stok dikurangi.'} Periksa alamat, depo, dan harga di checkout.</p><div class="actions">${btn('Batal',"pendingRepeat=null;$('#modal').close()",false)}${btn('Gunakan di keranjang','useRepeatCart()')}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function useRepeatCart(){if(!pendingRepeat)return;if(pendingRepeat.planId&&!db.orderPlans.some(p=>p.id===pendingRepeat.planId&&p.active))return toast('Template sudah dijeda atau tidak tersedia.');const c=db.customers.find(c=>c.id===pendingRepeat.customerId);if(!c)return toast('Pelanggan tidak tersedia.');repeatContext=pendingRepeat;pendingRepeat=null;cart={};for(const i of repeatContext.items)cart[i.product+'_'+i.unit]={...i};buyerCategory=c.category;checkoutCustomer=c.id;$('#modal').close();go('shop');toast('Keranjang disiapkan. Tinjau dan lanjutkan checkout untuk membuat pesanan.')}
function clearRepeatContext(){repeatContext=null;render();toast('Keranjang tetap ada; pesanan akan dibuat sebagai pesanan biasa.')}
function openFormRecurringBase(type,index){openFormLocationBase(type,index);if(type!=='checkout'||!repeatContext||!cartEntries().length)return;const form=$('#checkoutForm');form.elements.deliveryDate.value=repeatContext.deliveryDate;form.elements.deliverySlot.value=repeatContext.slot;form.elements.deliveryNotes.value=repeatContext.notes;const depot=db.depots.find(d=>d.name===repeatContext.depot);if(depot&&stockAllocation(depot).available){let point=null;try{point=deliveryPoint()}catch{}if(serviceEligibility(depot,point).allowed)form.elements.depot.value=depot.name}const banner=document.createElement('div');banner.className='notice';banner.textContent=(repeatContext.planId?'Template rutin':'Pesan ulang')+' · tanggal dan isi dapat ditinjau sebelum pesanan dibuat.';$('#modal').prepend(banner)}
function prepareOrderRoutineBase(r){prepareOrderRepeatBase(r);if(!repeatContext)return;if(r.customerId!==repeatContext.customerId)throw Error('Pelanggan berbeda dari template. Lepas template di toko untuk membuat pesanan biasa.');if(repeatContext.planId){const plan=db.orderPlans.find(p=>p.id===repeatContext.planId),c=db.customers.find(c=>c.id===plan?.customerId);if(!plan?.active||!c||plan.customerId!==repeatContext.customerId||c.category==='Perorangan'||c.category!==buyerCategory)throw Error('Template atau kategori pelanggan telah berubah. Tinjau ulang template.');if(db.orders.some(o=>o.recurringPlanId===plan.id&&o.deliveryDate===r.deliveryDate&&o.status!=='Dibatalkan'))throw Error('Pesanan template ini sudah ada pada tanggal tersebut. Pilih tanggal lain.');r.recurringPlanId=plan.id}if(repeatContext.sourceOrderId)r.sourceOrderId=repeatContext.sourceOrderId}
