function validateRecurring(data){const ids=new Set();if(data.orderPlans!==undefined){if(!Array.isArray(data.orderPlans)||data.orderPlans.length>10000)throw Error('Template pesanan tidak valid.');for(const p of data.orderPlans){if(typeof p.id!=='string'||!/^PLAN-(?:[A-F0-9]{8}|[A-F0-9]{32})$/.test(p.id)||ids.has(p.id)||typeof p.title!=='string'||!p.title.trim()||p.title.length>100||!data.customers?.some(c=>c.id===p.customerId)||!validDate(p.startDate)||p.startDate<'2000-01-01'||p.startDate>'2100-12-31'||!['Harian','Mingguan','Bulanan'].includes(p.cadence)||!['Pagi (08–12)','Siang (12–16)','Sore (16–20)'].includes(p.slot)||!data.depots.some(d=>d.name===p.depot)||typeof p.active!=='boolean'||typeof p.notes!=='string'||p.notes.length>300||!Array.isArray(p.items)||p.items.length<1||p.items.length>6)throw Error('Isi template pesanan tidak valid.');const units=new Set();for(const i of p.items){const key=i.product+'_'+i.unit;if(!Number.isInteger(i.product)||i.product<0||i.product>2||!['kg','butir'].includes(i.unit)||!Number.isFinite(i.quantity)||i.quantity<=0||(i.unit==='butir'&&!Number.isSafeInteger(i.quantity))||(i.unit==='kg'&&Math.abs(i.quantity*100-Math.round(i.quantity*100))>0.000001)||i.quantity>(i.unit==='kg'?100000:1000000)||units.has(key))throw Error('Jumlah template tidak valid.');units.add(key)}ids.add(p.id)}}const occurrences=new Set();for(const o of data.orders){if(o.recurringPlanId!==undefined){if(!ids.has(o.recurringPlanId)||!validDate(o.deliveryDate))throw Error('Referensi pesanan rutin tidak valid.');const key=o.recurringPlanId+'_'+o.deliveryDate;if(o.status!=='Dibatalkan'){if(occurrences.has(key))throw Error('Pesanan rutin ganda pada tanggal yang sama.');occurrences.add(key)}}if(o.sourceOrderId!==undefined&&(!data.orders.some(s=>s.id===o.sourceOrderId)||o.sourceOrderId===o.id))throw Error('Referensi pesan ulang tidak valid.')}}
function migrateCredit(data){data.customers?.forEach(c=>c.paymentTermsDays??=null);data.orders.forEach(o=>{o.paymentDueDate??=null;o.paymentTermHistory??=[]})}
function addCalendarDays(day,days){const date=new Date(day+'T00:00:00Z');date.setUTCDate(date.getUTCDate()+days);return date.toISOString().slice(0,10)}
function overdueDays(due,asOf=todayLocal()){if(!due)return null;return Math.floor((new Date(asOf+'T00:00:00Z')-new Date(due+'T00:00:00Z'))/86400000)}
function receivable(o,asOf=todayLocal()){const balance=o.status==='Dibatalkan'?0:financial(o).balance,days=overdueDays(o.paymentDueDate,asOf);let bucket=balance===0?'Lunas':days===null?'Belum ditetapkan':days<=0?'Belum lewat jatuh tempo':days<=30?'1–30 hari':days<=60?'31–60 hari':days<=90?'61–90 hari':'>90 hari';return {order:o,balance,paid:paid(o.id),days,bucket}}
let agingDay=todayLocal(),agingCategory='Semua',agingFilter='Semua',agingSearch='';
function agingRows(){return db.orders.map(o=>receivable(o,agingDay)).filter(r=>r.balance>0&&(agingCategory==='Semua'||r.order.buyerCategory===agingCategory)&&(agingFilter==='Semua'||(agingFilter==='Lewat jatuh tempo'&&r.days>0)||(agingFilter==='Belum lewat jatuh tempo'&&r.days!==null&&r.days<=0)||(agingFilter==='Belum ditetapkan'&&r.days===null))&&(r.order.name+' '+r.order.id).toLowerCase().includes(agingSearch.toLowerCase())).sort((a,b)=>(b.days??-100000)-(a.days??-100000))}
function enhanceCredit(){enhanceRecurring();if(page==='receivables')renderReceivables()}
function renderReceivables(){if(!validDate(agingDay)){agingDay=todayLocal()}const rows=agingRows(),all=db.orders.map(o=>receivable(o,agingDay)).filter(r=>r.balance>0);$('#app').innerHTML=title('Piutang & jatuh tempo','Saldo tagihan saat ini, dikelompokkan berdasarkan jatuh tempo pembayaran.',btn('↓ Ekspor piutang CSV','exportReceivables()',false))+`<div class="filters"><label>Tanggal acuan umur <input type="date" aria-label="Tanggal acuan umur piutang" value="${agingDay}" onchange="agingDay=this.value||todayLocal();renderReceivables()"></label><select aria-label="Kategori pembeli piutang" onchange="agingCategory=this.value;renderReceivables()">${['Semua','Perorangan','Wholesale','Hotel/Resort'].map(c=>`<option ${agingCategory===c?'selected':''}>${c}</option>`).join('')}</select><select aria-label="Status jatuh tempo" onchange="agingFilter=this.value;renderReceivables()">${['Semua','Lewat jatuh tempo','Belum lewat jatuh tempo','Belum ditetapkan'].map(c=>`<option ${agingFilter===c?'selected':''}>${c}</option>`).join('')}</select><input type="search" aria-label="Cari tagihan" placeholder="Nama atau nomor pesanan" value="${esc(agingSearch)}" oninput="agingSearch=this.value;renderAgingTable()"></div><div class="stats">${stat('Total piutang saat ini',money(all.reduce((s,r)=>s+r.balance,0)),'','Seluruh kategori · pesanan batal dikecualikan')}${stat('Lewat jatuh tempo',money(all.filter(r=>r.days>0).reduce((s,r)=>s+r.balance,0)),'','Berdasarkan tanggal acuan umur')}${stat('Tanpa jatuh tempo',money(all.filter(r=>r.days===null).reduce((s,r)=>s+r.balance,0)),'','Tidak diasumsikan sebagai keterlambatan')}${stat('Tagihan belum lunas',all.length,'tagihan','Pesanan aktif dan selesai')}</div><section class="card bottom"><h2 style="margin-bottom:15px">Umur piutang · hasil filter</h2><div id="agingBuckets">${table(['KELOMPOK UMUR','TAGIHAN','SALDO'],['Belum ditetapkan','Belum lewat jatuh tempo','1–30 hari','31–60 hari','61–90 hari','>90 hari'].map(bucket=>{const selected=rows.filter(r=>r.bucket===bucket);return `<tr><td>${bucket}</td><td>${selected.length}</td><td>${money(selected.reduce((s,r)=>s+r.balance,0))}</td></tr>`}))}</div></section><section class="card bottom"><h2 style="margin-bottom:15px">Rincian tagihan</h2><div id="agingTable"></div></section><div class="notice">Tanggal acuan hanya menentukan umur tagihan. Saldo mempertimbangkan pembayaran, nota kredit, dan refund yang dicatat saat ini, bukan rekonstruksi saldo historis. Tidak ada denda, bunga, atau pengingat yang dikirim otomatis.</div>`;renderAgingTable()}
function renderAgingTableBase(){$('#agingTable').innerHTML=table(['PELANGGAN / PESANAN','KATEGORI','JATUH TEMPO','UMUR LEWAT','NILAI PESANAN','DIBAYAR BERSIH','SISA','AKSI'],agingRows().map(r=>`<tr><td><strong>${esc(r.order.name)}</strong><p>${esc(r.order.id)}</p></td><td>${esc(r.order.buyerCategory)}</td><td>${r.order.paymentDueDate||'Belum ditetapkan'}</td><td>${r.days===null?'—':r.days>0?r.days+' hari':'Belum lewat'}</td><td>${money(r.netTotal)}</td><td>${money(r.paid)}</td><td><strong>${money(r.balance)}</strong></td><td><button class="textbtn" onclick="detail('${r.order.id}')">Detail</button><button class="textbtn" onclick="paymentForm('${r.order.id}');if(!$('#modal').open)$('#modal').showModal()">Bayar</button><button class="textbtn" onclick="dueDateForm('${r.order.id}')">Jatuh tempo</button></td></tr>`))}
function customerForm(id=''){customerTermBase(id);const c=db.customers.find(c=>c.id===id);$('#modal').innerHTML=$('#modal').innerHTML.replace('<label>Catatan (opsional)</label>',`<label>Termin pembayaran (hari, opsional)</label><input name="paymentTermsDays" type="number" min="0" max="3650" step="1" value="${c?.paymentTermsDays??''}" placeholder="Kosong = belum ditetapkan; 0 = tanggal pesanan"><p class="note">Termin menjadi saran jatuh tempo pesanan baru. Perubahan tidak mengubah tagihan lama.</p><label>Catatan (opsional)</label>`)}
function suggestedDueDate(customerId){const c=db.customers.find(c=>c.id===customerId);return c?.paymentTermsDays===null||c?.paymentTermsDays===undefined?'':addCalendarDays(todayLocal(),c.paymentTermsDays)}
function openFormCreditBase(type,index){openFormRecurringBase(type,index);if(type!=='checkout'||!cartEntries().length)return;const form=$('#checkoutForm'),due=suggestedDueDate(form.elements.customerId.value),block=document.createElement('div');block.className='locationbox';block.innerHTML=`<label>Jatuh tempo pembayaran (opsional)</label><input name="paymentDueDate" type="date" min="${todayLocal()}" value="${due}"><p class="note">Diisi dari termin pelanggan jika tersedia. Anda bisa menyesuaikan tanggal sebelum membuat pesanan; kosong berarti belum ditetapkan.</p>`;form.insertBefore(block,form.lastElementChild)}
function fillCustomer(id){fillCustomerPaymentBase(id);const form=$('#checkoutForm');if(form.elements.paymentDueDate)form.elements.paymentDueDate.value=suggestedDueDate(id)}
function prepareOrder(r){prepareOrderRoutineBase(r);if(r.paymentDueDate===undefined)r.paymentDueDate=suggestedDueDate(r.customerId);if(r.paymentDueDate==='')r.paymentDueDate=null;if(r.paymentDueDate!==null&&(!validDate(r.paymentDueDate)||r.paymentDueDate<todayLocal()))throw Error('Jatuh tempo pesanan baru harus hari ini atau setelahnya, atau dikosongkan.');r.paymentTermHistory=[]}
function dueDateForm(id){const o=db.orders.find(o=>o.id===id);if(!o||o.status==='Dibatalkan'||receivable(o).balance===0)return toast('Tagihan sudah lunas atau dibatalkan.');$('#modal').innerHTML=`<h2>Jatuh tempo ${esc(id)}</h2><p>Saldo tagihan ${money(receivable(o).balance)}</p><form onsubmit="saveDueDate(event,'${id}')"><label>Jatuh tempo pembayaran (opsional)</label><input name="paymentDueDate" type="date" value="${o.paymentDueDate||''}">${field('Alasan perubahan','reason','text','maxlength="300"')}<div class="notice">Tanggal dapat disesuaikan dengan kesepakatan yang sudah ada. Kosong berarti belum ditetapkan. Perubahan dicatat tanpa mengubah nilai pesanan atau pembayaran.</div><div class="actions"><button type="button" class="btn" onclick="detail('${id}')">Kembali</button><button class="btn primary">Simpan jatuh tempo</button></div></form>`;if(!$('#modal').open)$('#modal').showModal()}
function saveDueDate(e,id){e.preventDefault();const o=db.orders.find(o=>o.id===id),r=Object.fromEntries(new FormData(e.target));if(!o||o.status==='Dibatalkan'||receivable(o).balance===0)return toast('Tagihan sudah lunas atau dibatalkan.');const due=r.paymentDueDate||null;if((due!==null&&!validDate(due))||!r.reason.trim()||r.reason.length>300)return toast('Tanggal atau alasan perubahan tidak valid.');if(due===o.paymentDueDate)return toast('Jatuh tempo tidak berubah.');o.paymentTermHistory??=[];o.paymentTermHistory.push({time:new Date().toISOString(),previousDate:o.paymentDueDate,newDate:due,reason:r.reason.trim()});o.paymentDueDate=due;audit('Jatuh tempo '+id+' → '+(due||'Belum ditetapkan'));save();$('#modal').close();render();toast('Jatuh tempo disimpan. Riwayat perubahan tercatat.')}
function detailCreditBase(id){detailRepeatBase(id);const o=db.orders.find(o=>o.id===id);if(!o)return;const r=receivable(o);$('#modal').innerHTML+=`<div class="notice"><strong>Jatuh tempo: ${o.paymentDueDate||'Belum ditetapkan'}</strong><br>${o.status==='Dibatalkan'?'Tagihan dibatalkan':r.balance===0?'Pembayaran lunas':r.days===null?'Umur belum dapat dihitung':r.days>0?'Lewat '+r.days+' hari':'Belum lewat jatuh tempo'} · Sisa ${money(r.balance)}</div>${r.balance>0?`<div class="actions">${btn('Atur jatuh tempo',`dueDateForm('${id}')`,false)}</div>`:''}${o.paymentTermHistory?.length?`<h2 style="margin:20px 0 10px">Riwayat jatuh tempo</h2>${table(['SEBELUM','SESUDAH','ALASAN'],o.paymentTermHistory.map(h=>`<tr><td>${h.previousDate||'Belum ditetapkan'}</td><td>${h.newDate||'Belum ditetapkan'}</td><td>${esc(h.reason)}</td></tr>`))}`:''}`}
function invoiceCreditBase(o){return invoiceStockBase(o).replace('</article>',`<section style="margin-top:20px"><h2 style="margin-bottom:10px">Jatuh tempo pembayaran</h2><p><strong>${o.paymentDueDate||'Belum ditetapkan'}</strong></p><p class="note">${o.status==='Dibatalkan'?'Tagihan dibatalkan.':receivable(o).balance===0?'Pembayaran tercatat lunas.':'Sisa pembayaran '+money(receivable(o).balance)+'.'}</p></section></article>`)}
function exportReceivables(){const rows=[['Pesanan','Pelanggan','Kategori','Jatuh Tempo','Hari Lewat','Kelompok Umur','Nilai Pesanan Rp','Dibayar Rp','Saldo Rp'],...agingRows().map(r=>[r.order.id,r.order.name,r.order.buyerCategory,r.order.paymentDueDate||'',r.days===null?'':Math.max(0,r.days),r.bucket,r.order.total,r.paid,r.balance])],csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='PamanKu-Piutang-'+agingDay+'.csv';a.click();URL.revokeObjectURL(a.href)}
function validateCredit(data){for(const c of data.customers||[]){if(c.paymentTermsDays!==undefined&&c.paymentTermsDays!==null&&(!Number.isSafeInteger(c.paymentTermsDays)||c.paymentTermsDays<0||c.paymentTermsDays>3650))throw Error('Termin pelanggan tidak valid.')}for(const o of data.orders){if(o.paymentDueDate!==undefined&&o.paymentDueDate!==null&&!validDate(o.paymentDueDate))throw Error('Jatuh tempo pembayaran tidak valid.');if(o.paymentTermHistory!==undefined){if(!Array.isArray(o.paymentTermHistory)||o.paymentTermHistory.length>10000)throw Error('Riwayat jatuh tempo tidak valid.');for(let i=0;i<o.paymentTermHistory.length;i++){const h=o.paymentTermHistory[i];if(typeof h.time!=='string'||!Number.isFinite(Date.parse(h.time))||(h.previousDate!==null&&!validDate(h.previousDate))||(h.newDate!==null&&!validDate(h.newDate))||typeof h.reason!=='string'||!h.reason.trim()||h.reason.length>300||(i>0&&h.previousDate!==o.paymentTermHistory[i-1].newDate))throw Error('Isi riwayat jatuh tempo tidak valid.')}if(o.paymentTermHistory.length&&o.paymentTermHistory.at(-1).newDate!==o.paymentDueDate)throw Error('Jatuh tempo tidak sesuai riwayat perubahan.')}}}
function renderAgingTable(){renderAgingTableBase();const rows=agingRows();$('#agingBuckets').innerHTML=table(['KELOMPOK UMUR','TAGIHAN','SALDO'],['Belum ditetapkan','Belum lewat jatuh tempo','1–30 hari','31–60 hari','61–90 hari','>90 hari'].map(bucket=>{const selected=rows.filter(r=>r.bucket===bucket);return `<tr><td>${bucket}</td><td>${selected.length}</td><td>${money(selected.reduce((s,r)=>s+r.balance,0))}</td></tr>`}))}
let batchDepot='Semua',batchProduct='Semua',batchShowEmpty=false;
function batchDay(){const form=$('#checkoutForm'),v=form?.elements?.deliveryDate?.value;return v&&validDate(v)?v:todayLocal()}
function stockAllocation(depot){return planBatchAllocation(db,depot.name,cartEntries().map(([,l])=>({...l,name:products[l.product].name})),batchDay())}
function nearestDepots(point){if(!validPoint(point.latitude,point.longitude))throw Error('Titik lokasi tidak valid.');return db.depots.filter(d=>validPoint(d.latitude,d.longitude)).map(d=>{const service=serviceEligibility(d,point),allocation=stockAllocation(d);return {depot:d,distance:distanceKm(point,d),available:service.allowed&&allocation.available,reason:service.allowed?(allocation.reason||''):service.reason}}).sort((a,b)=>a.distance-b.distance)}
function totals(){const t=totalsAggregateBase();t.stockPhysical=t.stock;t.stock=batchRound(db.lots.filter(l=>lotEligible(l,todayLocal())&&l.kg>0&&l.eggs>0).reduce((s,l)=>s+l.kg,0));return t}
function enhance(){enhanceCredit();const date=$('#headDate');if(date)date.textContent=new Date().toLocaleDateString('id-ID',{timeZone:'Asia/Bangkok',day:'numeric',month:'long',year:'numeric'});if(page==='batches')renderBatches();if(page==='inventory')renderDepotInventory();if(page==='cases')renderCases();if(page==='guide')renderGuide();if(page==='finance')renderFinanceV3();if(page==='dashboard')renderDashboardV3();if(page==='shop'){const info=document.createElement('div');info.className='notice';info.textContent='Stok kini diperiksa per varian dan batch. Batch belum diklasifikasikan, diblokir, atau melewati batas jual tidak dialokasikan ke pesanan baru.';$('#app .intro').after(info)}}
function batchRows(){return db.lots.filter(l=>(batchDepot==='Semua'||l.depot===batchDepot)&&(batchProduct==='Semua'||String(l.product)===batchProduct)&&(batchShowEmpty||l.kg>0||l.eggs>0))}
function renderBatches(){const unclassified=db.lots.filter(l=>l.product===null&&(l.kg>0||l.eggs>0));$('#app').innerHTML=title('Batch & varian telur','Klasifikasikan, periksa, dan telusuri telur sebelum dijual.',btn('+ Batch masuk','batchForm()'))+`<div class="stats">${stat('Batch dengan stok',db.lots.filter(l=>l.kg>0||l.eggs>0).length,'batch','Stok tersedia di depo')}${stat('Belum diklasifikasikan',num(unclassified.reduce((s,l)=>s+l.kg,0)),'kg','Saldo tetap ada; pilih varian setelah pemeriksaan')}${stat('Lewat batas jual',db.lots.filter(l=>l.expiresOn&&l.expiresOn<todayLocal()&&(l.kg>0||l.eggs>0)).length,'batch','Dikecualikan dari pesanan baru')}${stat('Siap dialokasikan',num(totals().stock),'kg','Aktif, disetujui, sesuai varian')}</div>${unclassified.length?'<div class="setup-card"><strong>Saldo awal Anda tetap tersimpan.</strong><p>Gunakan Klasifikasi jika seluruh batch satu varian, atau Sortir sebagian untuk memisahkan reguler, pilihan, dan ekonomis sesuai pemeriksaan fisik.</p></div>':''}<div class="filters bottom"><select aria-label="Filter depo batch" onchange="batchDepot=this.value;renderBatchTable()">${['Semua',...db.depots.map(d=>d.name)].map(d=>`<option ${batchDepot===d?'selected':''}>${d}</option>`).join('')}</select><select aria-label="Filter varian batch" onchange="batchProduct=this.value;renderBatchTable()"><option value="Semua">Semua varian</option><option value="null" ${batchProduct==='null'?'selected':''}>Belum diklasifikasikan</option>${products.map((p,i)=>`<option value="${i}" ${batchProduct===String(i)?'selected':''}>${p.name}</option>`).join('')}</select><label><input type="checkbox" ${batchShowEmpty?'checked':''} onchange="batchShowEmpty=this.checked;renderBatchTable()"> Termasuk batch kosong/arsip</label></div><section class="card" id="batchTable"></section><div class="notice">Batas jual adalah tanggal operasional yang ditetapkan usaha; tidak dibuat otomatis. Batch dengan batas jual terdekat dialokasikan lebih dahulu (FEFO). Tanggal yang tidak diketahui tetap ditandai belum tercatat.</div>`;renderBatchTable()}
function renderBatchTable(){$('#batchTable').innerHTML=table(['BATCH / DEPO','VARIAN','STOK TERSEDIA','PANEN / BATAS JUAL','STATUS','AKSI'],batchRows().map(l=>`<tr><td><strong>${esc(l.code)}</strong><p>${esc(l.depot)}</p></td><td>${batchProductName(l.product)}</td><td>${num(l.kg)} kg<br>${num(l.eggs)} butir</td><td>${l.harvestDate||'Panen belum tercatat'}<p>${l.expiresOn||'Batas jual belum diatur'}</p></td><td>${tag(l.status)}<p>${l.approved?'Pemeriksaan tercatat':'Belum disetujui untuk penjualan baru'}</p></td><td><button class="textbtn" onclick="batchForm('${l.id}')">Klasifikasi</button><button class="textbtn" onclick="splitLotForm('${l.id}')">Sortir sebagian</button><button class="textbtn" onclick="lotTrace('${l.id}')">Telusuri</button></td></tr>`))}
function batchForm(id=''){const l=db.lots.find(l=>l.id===id)||{depot:db.depots[0].name,product:null,kg:'',eggs:'',harvestDate:null,expiresOn:null,status:'Karantina',approved:false,source:'',notes:''};$('#modal').innerHTML=`<h2>${id?'Klasifikasi & kualitas '+esc(l.code):'Batch masuk'}</h2><form onsubmit="saveLot(event,'${id}')">${id?`<p>${esc(l.depot)} · ${num(l.kg)} kg / ${num(l.eggs)} butir</p>`:sel('Depo','depot',db.depots.map(d=>d.name))}<label>Varian</label><select name="product"><option value="null">Belum diklasifikasikan</option>${products.map((p,i)=>`<option value="${i}" ${l.product===i?'selected':''}>${p.name}</option>`).join('')}</select>${!id?`<div class="formrow"><div>${field('Berat tersedia (kg)','kg','number','min="0.000001" step="any"')}</div><div>${field('Jumlah tersedia (butir)','eggs','number','min="1" step="1"')}</div></div>`:''}<div class="formrow"><div><label>Tanggal panen (jika diketahui)</label><input type="date" name="harvestDate" value="${l.harvestDate||''}"></div><div><label>Batas jual (jika ditetapkan)</label><input type="date" name="expiresOn" value="${l.expiresOn||''}"></div></div><label>Status kualitas</label><select name="status">${['Aktif','Karantina','Diblokir'].map(s=>`<option ${l.status===s?'selected':''}>${s}</option>`).join('')}</select><label><input type="checkbox" name="approved" style="width:auto" ${l.approved?'checked':''}> Varian dan kondisi telah saya periksa untuk penjualan</label>${field(id?'Alasan / catatan pemeriksaan':'Asal batch / keterangan','note','text','maxlength="300"')}<div class="notice">Varian batch yang sudah dirujuk pesanan tidak diubah agar arsip tetap benar. Saldo awal dan retur perlu diperiksa sebelum digunakan untuk penjualan baru.</div><div class="actions"><button type="button" class="btn" onclick="$('#modal').close()">Batal</button><button class="btn primary">Simpan batch</button></div></form>`;if(!$('#modal').open)$('#modal').showModal()}
function saveLot(e,id){e.preventDefault();const r=Object.fromEntries(new FormData(e.target)),product=r.product==='null'?null:Number(r.product),harvestDate=r.harvestDate||null,expiresOn=r.expiresOn||null,approved=r.approved==='on';if((product!==null&&(!Number.isInteger(product)||product<0||product>2))||(harvestDate&&!validDate(harvestDate))||(expiresOn&&!validDate(expiresOn))||(harvestDate&&expiresOn&&expiresOn<harvestDate)||!['Aktif','Karantina','Diblokir'].includes(r.status)||!r.note.trim()||r.note.length>300||(approved&&product===null))return toast('Lengkapi varian, status, tanggal, dan catatan dengan benar.');const current=db.lots.find(l=>l.id===id);if(id&&!current)return toast('Batch tidak ditemukan.');if(current){if(current.product!==product&&db.orders.some(o=>o.lotAllocations.some(a=>a.lotId===id)))return toast('Varian sudah dirujuk pesanan. Gunakan Sortir sebagian untuk stok yang belum dialokasikan.');Object.assign(current,{product,harvestDate,expiresOn,status:r.status,approved});current.qualityLog.push({time:new Date().toISOString(),note:r.note});current.notes=r.note}else{const kg=Number(r.kg),eggs=Number(r.eggs);if(!db.depots.some(d=>d.name===r.depot)||!Number.isFinite(kg)||kg<=0||!Number.isSafeInteger(eggs)||eggs<=0)return toast('Stok batch tidak valid.');db.lots.push(createLot({depot:r.depot,kg,eggs,product,harvestDate,expiresOn,status:r.status,approved,source:r.note}))}syncLotTotals(db);stockContext={type:id?'Pemeriksaan batch':'Batch masuk',note:r.note};audit((id?'Pemeriksaan':'Pencatatan')+' batch '+(id||r.depot));save();$('#modal').close();render();toast('Batch tersimpan. Stok depo dihitung dari batch.')}
function splitLotForm(id){const l=db.lots.find(l=>l.id===id);if(!l||l.kg<=0||l.eggs<=0||l.status==='Diblokir')return toast('Batch kosong atau diblokir. Lakukan pemeriksaan kualitas sebelum sortir.');$('#modal').innerHTML=`<h2>Sortir sebagian ${esc(l.code)}</h2><p>Stok sumber ${num(l.kg)} kg / ${num(l.eggs)} butir</p><form onsubmit="splitLot(event,'${id}')"><label>Varian hasil sortir</label><select name="product">${products.map((p,i)=>`<option value="${i}">${p.name}</option>`).join('')}</select>${field('Berat hasil sortir (kg)','kg','number','min="0.000001" step="any"')}${field('Jumlah hasil sortir (butir)','eggs','number','min="1" step="1"')}${field('Catatan pemeriksaan hasil sortir','note','text','maxlength="300"')}<div class="notice">Stok sumber berkurang dan batch hasil sortir bertambah dengan jumlah yang sama. Tanggal dan batas jual diwarisi dari sumber.</div><div class="actions"><button type="button" class="btn" onclick="$('#modal').close()">Batal</button><button class="btn primary">Simpan hasil sortir</button></div></form>`;if(!$('#modal').open)$('#modal').showModal()}
function splitLot(e,id){e.preventDefault();const l=db.lots.find(l=>l.id===id),r=Object.fromEntries(new FormData(e.target)),kg=Number(r.kg),eggs=Number(r.eggs),product=Number(r.product);if(!l||l.status==='Diblokir'||!Number.isFinite(kg)||kg<=0||kg>l.kg+0.0000001||!Number.isSafeInteger(eggs)||eggs<=0||eggs>l.eggs||!Number.isInteger(product)||product<0||product>2||!r.note.trim()||r.note.length>300)return toast('Jumlah atau varian hasil sortir tidak valid.');l.kg=batchRound(Math.max(0,l.kg-kg));l.eggs-=eggs;const child=createLot({depot:l.depot,kg,eggs,product,parentId:l.id,harvestDate:l.harvestDate,expiresOn:l.expiresOn,status:'Aktif',approved:true,legacy:l.legacy,source:'Hasil sortir '+l.code,notes:r.note});db.lots.push(child);l.qualityLog.push({time:new Date().toISOString(),note:'Sortir '+kg+' kg / '+eggs+' butir ke '+child.code});syncLotTotals(db);audit('Sortir '+l.code+' → '+child.code);save();$('#modal').close();render();toast('Hasil sortir tercatat tanpa menambah saldo total.')}
function lotTransferForm(){const options=db.lots.filter(l=>l.kg>0&&l.eggs>0);$('#modal').innerHTML=`<h2>Transfer batch antar depo</h2>${options.length?`<form onsubmit="transferLot(event)"><label>Batch sumber</label><select name="lotId">${options.map(l=>`<option value="${l.id}">${esc(l.code)} · ${esc(l.depot)} · ${batchProductName(l.product)}</option>`).join('')}</select>${sel('Depo tujuan','to',db.depots.map(d=>d.name))}${field('Berat transfer (kg)','kg','number','min="0.000001" step="any"')}${field('Jumlah transfer (butir)','eggs','number','min="1" step="1"')}${field('Catatan transfer','note','text','maxlength="300"')}<div class="actions"><button type="button" class="btn" onclick="$('#modal').close()">Batal</button><button class="btn primary">Transfer batch</button></div></form>`:'<div class="notice">Belum ada batch dengan stok tersedia.</div>'+btn('Tutup',"$('#modal').close()",false)}`;if(!$('#modal').open)$('#modal').showModal()}
function transferLot(e){e.preventDefault();const r=Object.fromEntries(new FormData(e.target)),l=db.lots.find(l=>l.id===r.lotId),kg=Number(r.kg),eggs=Number(r.eggs);if(!l||l.depot===r.to||!db.depots.some(d=>d.name===r.to)||!Number.isFinite(kg)||kg<=0||kg>l.kg+0.0000001||!Number.isSafeInteger(eggs)||eggs<=0||eggs>l.eggs||!r.note.trim()||r.note.length>300)return toast('Batch, depo tujuan, atau jumlah transfer tidak valid.');l.kg=batchRound(Math.max(0,l.kg-kg));l.eggs-=eggs;db.lots.push(createLot({...l,id:undefined,createdAt:undefined,parentId:l.id,depot:r.to,kg,eggs,source:'Transfer '+l.code+' dari '+l.depot,notes:r.note}));syncLotTotals(db);stockContext={type:'Transfer batch',note:l.code+' → '+r.to+' · '+r.note};audit('Transfer batch '+l.code);save();$('#modal').close();render();toast('Batch dipindahkan dengan asal dan status kualitas yang sama.')}
function stockChangeForm(){const lots=db.lots.filter(l=>l.kg>0||l.eggs>0);$('#modal').innerHTML=`<h2>Koreksi stok per batch</h2><form onsubmit="saveStockChange(event)"><label>Batch</label><select name="lotId">${lots.map(l=>`<option value="${l.id}">${esc(l.code)} · ${esc(l.depot)} · ${batchProductName(l.product)}</option>`).join('')}</select>${sel('Jenis perubahan','type',['Telur rusak','Kehilangan','Koreksi tambah','Koreksi kurang'])}${field('Berat (kg)','kg','number','min="0" step="any"')}${field('Jumlah (butir)','eggs','number','min="0" step="1"')}${field('Alasan','note','text','maxlength="300"')}<div class="actions"><button type="button" class="btn" onclick="$('#modal').close()">Batal</button><button class="btn primary">Catat koreksi</button></div></form>`;if(!$('#modal').open)$('#modal').showModal()}
function saveStockChange(e){e.preventDefault();const r=Object.fromEntries(new FormData(e.target)),l=db.lots.find(l=>l.id===r.lotId),kg=Number(r.kg),eggs=Number(r.eggs),sign=r.type==='Koreksi tambah'?1:-1;if(!l||!['Telur rusak','Kehilangan','Koreksi tambah','Koreksi kurang'].includes(r.type)||!Number.isFinite(kg)||kg<0||!Number.isSafeInteger(eggs)||eggs<0||(kg===0&&eggs===0)||(!r.type.startsWith('Koreksi')&&(kg===0||eggs===0))||!r.note.trim()||r.note.length>300||(sign<0&&(kg>l.kg+0.0000001||eggs>l.eggs)))return toast('Jumlah koreksi tidak valid atau melebihi stok batch tersedia.');l.kg=batchRound(Math.max(0,l.kg+sign*kg));l.eggs+=sign*eggs;l.qualityLog.push({time:new Date().toISOString(),note:r.type+' · '+r.note});syncLotTotals(db);stockContext={type:r.type,note:l.code+' · '+r.note};audit('Koreksi batch '+l.code);save();$('#modal').close();render();toast('Koreksi tercatat pada batch dan jurnal depo.')}
function submitForm(e,type){if(type==='checkout')return submitBatchOrder(e);if(type==='transfer')return transferLot(e);if(type==='production'){const r=Object.fromEntries(new FormData(e.target)),n=Object.fromEntries(['eggs','weight','broken','feed','dead'].map(k=>[k,Number(r[k])]));if(!validDate(r.date)||r.date>todayLocal()||!['Kandang A','Kandang B','Kandang C'].includes(r.house)||Object.values(n).some(x=>!Number.isFinite(x)||x<0)||['eggs','broken','dead'].some(k=>!Number.isSafeInteger(n[k]))||(n.eggs===0)!==(n.weight===0))return toast('Catat hasil aktual dengan tanggal, kandang, berat, dan butir yang valid.')}return submitFormRepeatBase(e,type)}
function submitBatchOrder(e){e.preventDefault();const r=Object.fromEntries(new FormData(e.target)),d=db.depots.find(d=>d.name===r.depot),entries=cartEntries();if(!d||!entries.length)return toast('Pilih depo dan isi keranjang.');try{prepareOrder(r);prepareLocation(r,d)}catch(err){return toast(err.message)}const items=entries.map(([,l])=>({...l,name:products[l.product].name,unitPrice:price(l.product,l.unit),subtotal:Math.round(l.quantity*price(l.product,l.unit))})),allocation=planBatchAllocation(db,d.name,items,r.deliveryDate);if(!allocation.available)return toast(allocation.reason);for(const a of allocation.allocations){const l=db.lots.find(l=>l.id===a.lotId);l.kg=batchRound(Math.max(0,l.kg-a.kg));l.eggs-=a.eggs}attachCustomer(r);const id='TF-'+crypto.randomUUID().replaceAll('-','').toUpperCase();db.orders.unshift({...r,id,items,kg:allocation.kg,stockEggs:allocation.eggs,lotAllocations:allocation.allocations,legacyInventory:false,buyerCategory,total:items.reduce((s,i)=>s+i.subtotal,0),product:items.map(i=>i.name+' ('+num(i.quantity)+' '+i.unit+')').join(', '),status:'Diproses'});syncLotTotals(db);cart={};repeatContext=null;page='orders';audit('Pesanan '+id+' · alokasi batch per varian');save();$('#modal').close();render();toast('Pesanan dibuat dengan batch sesuai varian dan tanggal pengiriman.')}
function cancelOrder(id){const o=db.orders.find(o=>o.id===id);if(!o||o.status!=='Diproses'||paid(id)>0)return toast('Pembatalan hanya sebelum pengiriman dan pembayaran.');for(const a of o.lotAllocations){const l=db.lots.find(l=>l.id===a.lotId);l.kg=batchRound(l.kg+a.kg);l.eggs+=a.eggs;if(o.legacyInventory){l.approved=false;l.status='Karantina'}}o.status='Dibatalkan';syncLotTotals(db);stockContext={type:'Pengembalian alokasi batch',note:id};audit('Pembatalan '+id);save();$('#modal').close();render();toast('Stok kembali ke batch asal. Batch reservasi lama perlu pemeriksaan sebelum dijual ulang.')}
function openForm(type,index){if(type==='transfer')return lotTransferForm();if(type==='stock')return stockChangeForm();openFormCreditBase(type,index);if(type==='checkout'&&cartEntries().length){const field=$('#checkoutForm').elements.deliveryDate;field.addEventListener?.('change',()=>{try{deliveryPoint();findNearest()}catch{}})}if(type==='production'){const notice=document.createElement('p');notice.className='notice';notice.textContent='Hasil panen masuk sebagai batch belum diklasifikasikan. Lanjutkan sortir varian di menu Batch & varian telur.';$('#modal').append(notice)}}
function packingForm(id){const o=db.orders.find(o=>o.id===id);if(!o||o.status!=='Diproses')return;const lines=batchOrderLines(o),owned=new Set(o.lotAllocations.map(a=>a.lotId)),day=o.deliveryDate>todayLocal()?o.deliveryDate:todayLocal();$('#modal').innerHTML=`<h2>Hitung & timbang ${esc(id)}</h2><p>Isi hasil fisik untuk setiap batch. Jumlah pada satuan yang dibeli harus sesuai pesanan; 0 kg dan 0 butir dapat dipakai untuk mengosongkan baris batch.</p><form onsubmit="savePacking(event,'${id}')">${o.lotAllocations.map((a,i)=>{const line=lines[a.itemIndex],options=db.lots.filter(l=>l.depot===o.depot&&l.product===batchLineProduct(line)&&lotEligible(l,day,o.legacyInventory?owned:new Set())&&(l.kg>0||owned.has(l.id)));return `<div class="lot-selection"><strong>${esc(line.name)} · item ${a.itemIndex+1}</strong><p>Pesanan ${num(line.quantity)} ${line.unit}</p><label>Batch sumber</label><select name="lot${i}">${options.map(l=>`<option value="${l.id}" ${l.id===a.lotId?'selected':''}>${esc(l.code)} · ${l.expiresOn||'batas belum diatur'}${l.legacy?' · sumber migrasi':''}</option>`).join('')}</select><div class="formrow"><div>${field('Berat aktual (kg)','kg'+i,'number',`min="0" step="any" value="${a.kg}"`)}</div><div>${field('Butir aktual','eggs'+i,'number',`min="0" step="1" value="${a.eggs}"`)}</div></div></div>`}).join('')}${field('Catatan pemeriksaan','note','text',`maxlength="300" value="${esc(o.packing?.note||'')}"`)}<div class="notice">Batch terpilih dicatat pada pesanan. Data asal batch sebelum v3.0 tetap ditandai sebagai snapshot lama.</div><div class="actions"><button type="button" class="btn" onclick="detail('${id}')">Kembali</button><button class="btn primary">Simpan hasil fisik</button></div></form>`;if(!$('#modal').open)$('#modal').showModal()}
function savePacking(e,id){e.preventDefault();const o=db.orders.find(o=>o.id===id),r=Object.fromEntries(new FormData(e.target));if(!o||o.status!=='Diproses'||!r.note.trim()||r.note.length>300)return toast('Pesanan atau catatan tidak valid.');const lines=batchOrderLines(o),owned=new Set(o.lotAllocations.map(a=>a.lotId)),working=db.lots.map(l=>({...l}));for(const a of o.lotAllocations){const l=working.find(l=>l.id===a.lotId);l.kg=batchRound(l.kg+a.kg);l.eggs+=a.eggs}const next=[],day=o.deliveryDate>todayLocal()?o.deliveryDate:todayLocal();for(let i=0;i<o.lotAllocations.length;i++){const old=o.lotAllocations[i],kg=Number(r['kg'+i]),eggs=Number(r['eggs'+i]);if(kg===0&&eggs===0)continue;const l=working.find(l=>l.id===r['lot'+i]);if(!l||l.depot!==o.depot||l.product!==batchLineProduct(lines[old.itemIndex])||!lotEligible(l,day,o.legacyInventory?owned:new Set())||!Number.isFinite(kg)||kg<=0||!Number.isSafeInteger(eggs)||eggs<=0||kg>l.kg+0.0000001||eggs>l.eggs)return toast('Hasil ukur melebihi batch, varian berbeda, atau batch tidak layak untuk tanggal kirim.');l.kg=batchRound(Math.max(0,l.kg-kg));l.eggs-=eggs;next.push({lotId:l.id,itemIndex:old.itemIndex,kg:batchRound(kg),eggs})}const items=lines.map((line,i)=>({name:line.name,unit:line.unit,quantity:line.quantity,kg:batchRound(next.filter(a=>a.itemIndex===i).reduce((s,a)=>s+a.kg,0)),eggs:next.filter(a=>a.itemIndex===i).reduce((s,a)=>s+a.eggs,0)}));if(items.some(i=>i.kg<=0||i.eggs<=0||(i.unit==='kg'&&Math.abs(i.kg-i.quantity)>0.000001)||(i.unit==='butir'&&i.eggs!==i.quantity)))return toast('Total hasil ukur per item tidak sesuai satuan dan jumlah yang dibeli.');db.lots=working;o.lotAllocations=next;o.kg=batchRound(next.reduce((s,a)=>s+a.kg,0));o.stockEggs=next.reduce((s,a)=>s+a.eggs,0);o.packing={items,note:r.note,time:new Date().toISOString()};syncLotTotals(db);stockContext={type:'Hasil fisik per batch',note:id+' · '+r.note};deliveryEvent(o,'Hitung & timbang batch',num(o.kg)+' kg / '+o.stockEggs+' butir');save();$('#modal').close();render();toast('Hasil fisik dan batch dicatat; harga invoice tetap.')}
function advance(id){const o=db.orders.find(o=>o.id===id);if(o?.status==='Diproses'){if(!o.packing)return toast('Catat hitung dan timbang per batch sebelum pengiriman.');const owned=new Set(o.lotAllocations.map(a=>a.lotId)),day=o.deliveryDate>todayLocal()?o.deliveryDate:todayLocal();if(o.lotAllocations.some(a=>!lotEligible(db.lots.find(l=>l.id===a.lotId),day,o.legacyInventory?owned:new Set())))return toast('Ada batch diblokir, dikarantina, atau lewat batas jual. Periksa kembali batch pesanan.')}return advancePackedBase(id)}
function lotRoot(id){let l=db.lots.find(l=>l.id===id),seen=new Set();while(l?.parentId&&!seen.has(l.id)){seen.add(l.id);l=db.lots.find(x=>x.id===l.parentId)||l}return l}
function lotTrace(id){const l=db.lots.find(l=>l.id===id);if(!l)return;const root=lotRoot(id),family=db.lots.filter(x=>lotRoot(x.id)?.id===root.id),ids=new Set(family.map(x=>x.id)),orders=db.orders.filter(o=>o.lotAllocations.some(a=>ids.has(a.lotId)));$('#modal').innerHTML=`<h2>Telusur ${esc(l.code)}</h2><div class="notice">${esc(l.source)}<br>Panen: ${l.harvestDate||'Belum tercatat'} · Batas jual: ${l.expiresOn||'Belum diatur'}${l.legacy?'<br><strong>Sumber sebelum v3.0 belum dapat dianggap sebagai bukti asal panen.</strong>':''}</div><h2 style="margin:20px 0 10px">Cabang & stok batch</h2>${table(['BATCH','DEPO','VARIAN','SALDO'],family.map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.depot)}</td><td>${batchProductName(x.product)}</td><td>${num(x.kg)} kg / ${x.eggs}</td></tr>`))}<div class="actions">${btn('Tutup',"$('#modal').close()",false)}${btn('Cetak label',`printLotLabel('${l.id}')`,false)}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function printLotLabel(id){const l=db.lots.find(l=>l.id===id);if(!l)return;$('#modal').close();$('#invoice').innerHTML=`<div class="print-actions">${btn('Kembali','closeInvoice()',false)}${btn('Cetak / Simpan PDF','printInvoice()')}</div><article class="invoice-paper"><div class="brand">PamanKu</div><h1 style="margin-top:20px">${esc(l.code)}</h1><h2>${batchProductName(l.product)}</h2><p>Depo: ${esc(l.depot)}</p><p>Panen: ${l.harvestDate||'Belum tercatat'}</p><p>Batas jual: ${l.expiresOn||'Belum diatur'}</p><p>Status: ${esc(l.status)}</p><p>${esc(l.source)}</p><p class="note">ID ${l.id} · label data batch, bukan sertifikat kualitas.</p></article>`;$('#invoice').hidden=false;document.body.classList.add('printing-invoice')}
function renderDepotInventory(){$('#app').innerHTML=title('Stok & jaringan depo','Saldo fisik tersedia dihitung dari batch, termasuk batch yang belum layak jual.',btn('Transfer batch',"lotTransferForm()"))+`<div class="products">${db.depots.map(d=>{const lots=db.lots.filter(l=>l.depot===d.name);return `<section class="card"><h2>${d.name}</h2><p>${d.area}</p><div class="value">${num(d.stock)} <small>kg fisik tersedia</small></div><strong>${num(d.eggs)} butir</strong>${products.map((p,i)=>{const ready=lots.filter(l=>l.product===i&&lotEligible(l,todayLocal())&&l.kg>0&&l.eggs>0);return `<div class="cartline"><span>${p.name}</span><strong>${num(batchRound(ready.reduce((s,l)=>s+l.kg,0)))} kg</strong></div>`}).join('')}<p class="note">Siap jual hari ini per varian. Reservasi pesanan tidak termasuk saldo tersedia.</p><button class="textbtn" onclick="batchDepot='${d.name}';go('batches')">Kelola batch →</button></section>`}).join('')}</div><section class="card"><div class="cardhead"><h2>Lokasi & area layanan</h2><span class="tag">Koordinat contoh perlu diperiksa</span></div>${table(['DEPO','LOKASI','RADIUS','AKSI'],db.depots.map((d,i)=>`<tr><td>${d.name}</td><td>${d.latitude}, ${d.longitude}<p>${d.locationDemo?'Koordinat contoh':'Lokasi telah diatur'}</p></td><td>${d.deliveryActive?(d.serviceRadiusKm?d.serviceRadiusKm+' km':'Belum dibatasi'):'Nonaktif'}</td><td><button class="textbtn" onclick="depotLocationForm(${i})">Atur lokasi</button><button class="textbtn" onclick="coverageForm(${i})">Atur layanan</button></td></tr>`))}</section><section class="card bottom"><div class="cardhead"><h2>Jurnal stok depo</h2>${btn('+ Koreksi batch','stockChangeForm()',false)}</div><div class="filters"><select onchange="stockDepotFilter=this.value;renderStockJournal()" aria-label="Filter jurnal depo">${['Semua',...db.depots.map(d=>d.name)].map(d=>`<option ${d===stockDepotFilter?'selected':''}>${d}</option>`).join('')}</select>${btn('↓ Ekspor jurnal','exportStockJournal()',false)}</div><div id="stockJournalTable"></div></section>`;renderStockJournal()}
function financial(o){return financialFor(db,o)}
function receivable(o,asOf=todayLocal()){const f=financial(o),days=overdueDays(o.paymentDueDate,asOf),bucket=f.balance===0?'Terselesaikan':days===null?'Belum ditetapkan':days<=0?'Belum lewat jatuh tempo':days<=30?'1–30 hari':days<=60?'31–60 hari':days<=90?'61–90 hari':'>90 hari';return {order:o,balance:f.balance,paid:f.netPaid,days,bucket,...f}}
function caseForm(orderId=''){const orders=db.orders.filter(o=>o.status!=='Dibatalkan');$('#modal').innerHTML=`<h2>Catat keluhan / retur</h2><form onsubmit="saveCase(event)"><label>Pesanan</label><select name="orderId">${orders.map(o=>`<option value="${o.id}" ${o.id===orderId?'selected':''}>${o.id} · ${esc(o.name)}</option>`).join('')}</select>${sel('Jenis kasus','kind',['Keluhan','Retur'])}${field('Keterangan pelanggan / masalah','description','text','maxlength="500"')}<div class="notice">Pencatatan kasus belum menambah stok atau mengubah tagihan. Penerimaan barang, nota kredit, dan refund dicatat melalui tindakan terpisah.</div><div class="actions"><button type="button" class="btn" onclick="$('#modal').close()">Batal</button><button class="btn primary">Simpan kasus</button></div></form>`;if(!$('#modal').open)$('#modal').showModal()}
function saveCase(e){e.preventDefault();const r=Object.fromEntries(new FormData(e.target)),o=db.orders.find(o=>o.id===r.orderId);if(!o||o.status==='Dibatalkan'||!['Keluhan','Retur'].includes(r.kind)||!r.description.trim()||r.description.length>500)return toast('Pesanan dan keterangan kasus diperlukan.');db.cases.unshift({id:'CASE-'+crypto.randomUUID().replaceAll('-','').toUpperCase(),orderId:o.id,kind:r.kind,description:r.description.trim(),status:'Terbuka',resolution:'',createdAt:new Date().toISOString()});audit('Kasus '+r.kind+' '+o.id);save();$('#modal').close();page='cases';render();toast('Kasus tercatat untuk ditindaklanjuti.')}
function renderCases(){const refundDue=db.orders.reduce((s,o)=>s+financial(o).refundDue,0);$('#app').innerHTML=title('Keluhan & retur','Pisahkan penerimaan fisik barang, koreksi tagihan, dan pengembalian dana.',btn('+ Catat kasus','caseForm()'))+`<div class="stats">${stat('Kasus terbuka',db.cases.filter(c=>c.status!=='Ditutup').length,'kasus','Keluhan dan retur belum ditutup')}${stat('Retur diterima',db.cases.filter(c=>c.returnReceipt).length,'kasus','Barang kembali masuk karantina')}${stat('Nota kredit tercatat',money(db.cases.reduce((s,c)=>s+(c.credit?.amount||0),0)),'','Mengurangi nilai tagihan')}${stat('Refund masih perlu dicatat',money(refundDue),'','Dari kelebihan pembayaran setelah kredit')}</div><section class="card bottom">${table(['KASUS / PESANAN','JENIS','KETERANGAN','STATUS','FISIK / KREDIT','AKSI'],db.cases.map(c=>`<tr><td><strong>${c.id}</strong><p>${c.orderId}</p></td><td>${c.kind}</td><td>${esc(c.description)}</td><td>${tag(c.status)}</td><td>${c.returnReceipt?'Retur diterima':'Belum ada penerimaan retur'}<p>${c.credit?money(c.credit.amount):'Belum ada kredit'}</p></td><td><button class="textbtn" onclick="caseDetail('${c.id}')">Tindak lanjut →</button></td></tr>`))}</section><section class="card bottom"><h2 style="margin-bottom:15px">Refund yang sudah dicatat</h2>${table(['TANGGAL','PESANAN','METODE','REFERENSI','JUMLAH'],db.refunds.map(r=>`<tr><td>${r.date}</td><td>${r.orderId}</td><td>${esc(r.method)}</td><td>${esc(r.reference)}</td><td>${money(r.amount)}</td></tr>`))}</section><div class="notice">Refund adalah pencatatan dana yang telah dikembalikan secara manual. Aplikasi tidak mengirim uang ke bank atau mengirim pesan kepada pelanggan.</div>`}
function refundAvailable(c){const o=db.orders.find(o=>o.id===c.orderId),remaining=(c.credit?.amount||0)-db.refunds.filter(r=>r.caseId===c.id).reduce((s,r)=>s+r.amount,0);return Math.max(0,Math.min(remaining,financial(o).refundDue))}
function caseDetail(id){const c=db.cases.find(c=>c.id===id),o=c&&db.orders.find(o=>o.id===c.orderId);if(!c||!o)return;const f=financial(o);$('#modal').innerHTML=`<h2>${c.id}</h2><p>${esc(o.name)} · ${c.orderId}</p><div class="notice">${esc(c.description)}<br>Status: ${esc(c.status)}<br>Saldo tagihan ${money(f.balance)} · Refund tertunda ${money(f.refundDue)}</div>${c.returnReceipt?`<p>Retur diterima ${new Date(c.returnReceipt.time).toLocaleString('id-ID',{timeZone:'Asia/Bangkok'})}; barang masuk karantina.</p>`:''}${c.credit?`<p>Nota kredit ${money(c.credit.amount)} · ${esc(c.credit.reason)}</p>`:''}${c.resolution?`<p>Penyelesaian: ${esc(c.resolution)}</p>`:''}<div class="actions">${btn('Tutup',"$('#modal').close()",false)}${c.kind==='Retur'&&!c.returnReceipt&&['Dalam pengiriman','Selesai'].includes(o.status)?btn('Terima barang retur',`returnForm('${id}')`,false):''}${!c.credit&&['Dalam pengiriman','Selesai'].includes(o.status)&&o.total-f.credits>0?btn('Nota kredit',`creditForm('${id}')`,false):''}${refundAvailable(c)>0?btn('Catat refund',`refundForm('${id}')`,false):''}${c.status!=='Ditutup'?btn('Status & penyelesaian',`resolveCaseForm('${id}')`,false):''}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function returnedFromLot(orderId,itemIndex,lotId){return db.cases.filter(c=>c.orderId===orderId&&c.returnReceipt).flatMap(c=>c.returnReceipt.items).filter(r=>r.itemIndex===itemIndex&&r.originLotId===lotId).reduce((s,r)=>({kg:s.kg+r.kg,eggs:s.eggs+r.eggs}),{kg:0,eggs:0})}
function returnedFor(orderId,itemIndex){return db.cases.filter(c=>c.orderId===orderId&&c.returnReceipt).flatMap(c=>c.returnReceipt.items).filter(r=>r.itemIndex===itemIndex).reduce((s,r)=>({kg:s.kg+r.kg,eggs:s.eggs+r.eggs}),{kg:0,eggs:0})}
function returnForm(id){const c=db.cases.find(c=>c.id===id),o=c&&db.orders.find(o=>o.id===c.orderId);if(!c||c.returnReceipt||!['Dalam pengiriman','Selesai'].includes(o.status))return;$('#modal').innerHTML=`<h2>Terima retur ${id}</h2><p>Isi jumlah yang benar-benar diterima di depo. Gunakan 0 untuk item yang tidak diretur.</p><form onsubmit="receiveReturn(event,'${id}')">${batchOrderLines(o).map((line,i)=>{const shipped=batchMeasuredLine(o,i),old=returnedFor(o.id,i);return `<div class="lot-selection"><strong>${esc(line.name)}</strong><p>Maksimal belum diretur: ${num(batchRound(shipped.kg-old.kg))} kg / ${shipped.eggs-old.eggs} butir</p><label>Asal batch bila diketahui</label><select name="origin${i}"><option value="">Asal batch belum diketahui</option>${o.lotAllocations.filter(a=>a.itemIndex===i).map(a=>{const l=db.lots.find(l=>l.id===a.lotId);return `<option value="${l.id}">${esc(l.code)}</option>`}).join('')}</select><div class="formrow"><div><label>Berat diterima (kg)</label><input name="kg${i}" type="number" min="0" step="any" value="0"></div><div><label>Butir diterima</label><input name="eggs${i}" type="number" min="0" step="1" value="0"></div></div></div>`}).join('')}${field('Catatan penerimaan','note','text','maxlength="300"')}<div class="notice">Penerimaan hanya sekali per kasus. Barang masuk batch karantina dan tidak otomatis dijual ulang. Nilai tagihan tetap sampai nota kredit disetujui.</div><div class="actions"><button type="button" class="btn" onclick="caseDetail('${id}')">Kembali</button><button class="btn primary">Terima ke karantina</button></div></form>`}
function receiveReturn(e,id){e.preventDefault();const c=db.cases.find(c=>c.id===id),o=c&&db.orders.find(o=>o.id===c.orderId),r=Object.fromEntries(new FormData(e.target));if(!c||c.kind!=='Retur'||c.returnReceipt||!['Dalam pengiriman','Selesai'].includes(o.status)||!r.note.trim()||r.note.length>300)return toast('Retur belum siap diterima atau sudah pernah diterima.');const items=[];for(let i=0;i<batchOrderLines(o).length;i++){const kg=Number(r['kg'+i]),eggs=Number(r['eggs'+i]);if(kg===0&&eggs===0)continue;const shipped=batchMeasuredLine(o,i),old=returnedFor(o.id,i),originLotId=r['origin'+i]||null;if(!Number.isFinite(kg)||kg<=0||!Number.isSafeInteger(eggs)||eggs<=0||kg+old.kg>shipped.kg+0.000001||eggs+old.eggs>shipped.eggs||(originLotId&&!o.lotAllocations.some(a=>a.itemIndex===i&&a.lotId===originLotId)))return toast('Jumlah retur melebihi pengiriman atau asal batch tidak sesuai.');if(originLotId){const allocated=o.lotAllocations.filter(a=>a.itemIndex===i&&a.lotId===originLotId).reduce((s,a)=>({kg:s.kg+a.kg,eggs:s.eggs+a.eggs}),{kg:0,eggs:0}),prior=returnedFromLot(o.id,i,originLotId);if(kg+prior.kg>allocated.kg+0.000001||eggs+prior.eggs>allocated.eggs)return toast('Retur melebihi jumlah dari batch asal yang dipilih.')}items.push({itemIndex:i,kg:batchRound(kg),eggs,originLotId})}if(!items.length)return toast('Isi minimal satu item retur yang diterima.');for(const i of items){const origin=db.lots.find(l=>l.id===i.originLotId),product=batchLineProduct(batchOrderLines(o)[i.itemIndex]),lot=createLot({depot:o.depot,product:product<0?null:product,kg:i.kg,eggs:i.eggs,parentId:origin?.id||null,code:origin?.code,harvestDate:origin?.harvestDate||null,expiresOn:origin?.expiresOn||null,status:'Karantina',approved:false,caseId:c.id,source:'Retur '+c.id+' dari '+o.id,notes:r.note});db.lots.push(lot);i.returnLotId=lot.id}c.returnReceipt={items,time:new Date().toISOString(),note:r.note};c.status='Ditindaklanjuti';syncLotTotals(db);stockContext={type:'Retur diterima ke karantina',note:c.id+' · '+r.note};const full=batchOrderLines(o).every((line,i)=>{const returned=returnedFor(o.id,i),shipped=batchMeasuredLine(o,i);return Math.abs(returned.kg-shipped.kg)<=0.000001&&returned.eggs===shipped.eggs});if(full&&o.status==='Dalam pengiriman'){o.status='Selesai';o.fulfillmentResult='Dikembalikan';o.returnedToDepotAt=new Date().toISOString();deliveryEvent(o,'Pengiriman kembali ke depo',c.id)}audit('Penerimaan retur '+c.id);save();$('#modal').close();render();toast('Retur masuk karantina. Tinjau nota kredit untuk koreksi tagihan.')}
function creditForm(id){const c=db.cases.find(c=>c.id===id),o=c&&db.orders.find(o=>o.id===c.orderId);if(!c||c.credit||!['Dalam pengiriman','Selesai'].includes(o.status))return;const max=o.total-financial(o).credits;$('#modal').innerHTML=`<h2>Persetujuan nota kredit</h2><p>${id} · ${o.id}</p><form onsubmit="approveCredit(event,'${id}')">${field('Kredit tagihan disetujui (Rp)','amount','number',`min="1" max="${max}" step="1"`)}${field('Alasan persetujuan','reason','text','maxlength="300"')}<div class="notice">Kredit mengurangi nilai tagihan dan dapat menimbulkan hak refund jika dana sudah diterima. Maksimal sisa nilai pesanan ${money(max)}. Kredit yang disimpan menjadi catatan tetap.</div><div class="actions"><button type="button" class="btn" onclick="caseDetail('${id}')">Kembali</button><button class="btn primary">Setujui kredit</button></div></form>`}
function approveCredit(e,id){e.preventDefault();const c=db.cases.find(c=>c.id===id),o=c&&db.orders.find(o=>o.id===c.orderId),r=Object.fromEntries(new FormData(e.target)),amount=Number(r.amount);if(!c||c.credit||!['Dalam pengiriman','Selesai'].includes(o.status)||!Number.isSafeInteger(amount)||amount<=0||amount>o.total-financial(o).credits||!r.reason.trim()||r.reason.length>300)return toast('Nilai kredit tidak valid atau kredit sudah disimpan.');c.credit={amount,reason:r.reason.trim(),time:new Date().toISOString()};c.status='Ditindaklanjuti';audit('Nota kredit '+c.id+' '+money(amount));save();$('#modal').close();render();toast('Nota kredit tersimpan; piutang dan hak refund dihitung ulang.')}
function refundForm(id){const c=db.cases.find(c=>c.id===id);if(!c||refundAvailable(c)<=0)return;$('#modal').innerHTML=`<h2>Catat dana sudah dikembalikan</h2><p>${id} · maksimal ${money(refundAvailable(c))}</p><form onsubmit="recordRefund(event,'${id}')">${field('Tanggal pengembalian dana','date','date',`max="${todayLocal()}" value="${todayLocal()}"`)}${field('Jumlah sudah dikembalikan (Rp)','amount','number',`min="1" max="${refundAvailable(c)}" step="1"`)}${sel('Metode','method',['Transfer bank','Tunai','QRIS'])}${field('Referensi / bukti transaksi','reference','text','maxlength="150"')}<div class="notice">Isi setelah pengembalian dana benar-benar dilakukan. Tombol ini mencatat transaksi dan tidak mengirim uang.</div><div class="actions"><button type="button" class="btn" onclick="caseDetail('${id}')">Kembali</button><button class="btn primary">Simpan refund tercatat</button></div></form>`}
function recordRefund(e,id){e.preventDefault();const c=db.cases.find(c=>c.id===id),r=Object.fromEntries(new FormData(e.target)),amount=Number(r.amount);if(!c||!validDate(r.date)||r.date>todayLocal()||!Number.isSafeInteger(amount)||amount<=0||amount>refundAvailable(c)||!['Transfer bank','Tunai','QRIS'].includes(r.method)||!r.reference.trim()||r.reference.length>150)return toast('Tanggal, jumlah, atau referensi refund tidak valid.');db.refunds.push({id:'RFD-'+crypto.randomUUID().replaceAll('-','').toUpperCase(),caseId:c.id,orderId:c.orderId,date:r.date,amount,method:r.method,reference:r.reference.trim()});audit('Refund tercatat '+c.id+' '+money(amount));save();$('#modal').close();render();toast('Refund dicatat; saldo dan kewajiban pengembalian diperbarui.')}
function resolveCaseForm(id){const c=db.cases.find(c=>c.id===id);if(!c)return;$('#modal').innerHTML=`<h2>Status kasus ${id}</h2><form onsubmit="resolveCase(event,'${id}')">${sel('Status','status',['Ditindaklanjuti','Ditutup'])}${field('Catatan tindak lanjut / penyelesaian','resolution','text','maxlength="500"')}<div class="actions"><button type="button" class="btn" onclick="caseDetail('${id}')">Kembali</button><button class="btn primary">Simpan status</button></div></form>`}
function resolveCase(e,id){e.preventDefault();const c=db.cases.find(c=>c.id===id),r=Object.fromEntries(new FormData(e.target));if(!c||!['Ditindaklanjuti','Ditutup'].includes(r.status)||!r.resolution.trim()||r.resolution.length>500)return toast('Status dan catatan penyelesaian diperlukan.');if(r.status==='Ditutup'&&c.credit&&refundAvailable(c)>0)return toast('Catat refund yang masih menjadi hak pelanggan sebelum menutup kasus.');c.status=r.status;c.resolution=r.resolution.trim();audit('Kasus '+id+' → '+c.status);save();$('#modal').close();render();toast('Status kasus diperbarui.')}
function paymentForm(id){const o=db.orders.find(o=>o.id===id);if(!o||financial(o).balance<=0)return toast('Tagihan sudah terselesaikan.');$('#modal').innerHTML=`<h2>Catat pembayaran ${id}</h2><p>Sisa setelah nota kredit ${money(financial(o).balance)}</p><form onsubmit="recordPayment(event,'${id}')">${field('Tanggal diterima','date','date',`value="${todayLocal()}"`)}${field('Jumlah (Rp)','amount','number',`min="1" max="${financial(o).balance}" step="1"`)}${sel('Metode','method',['Transfer bank','Tunai','QRIS'])}${field('Referensi','reference','text','maxlength="150"')}<div class="actions"><button type="button" class="btn" onclick="detail('${id}')">Kembali</button><button class="btn primary">Simpan pembayaran</button></div></form>`;if(!$('#modal').open)$('#modal').showModal()}
function recordPayment(e,id){e.preventDefault();const o=db.orders.find(o=>o.id===id),r=Object.fromEntries(new FormData(e.target)),amount=Number(r.amount);if(!o||o.status==='Dibatalkan'||!validDate(r.date)||!Number.isSafeInteger(amount)||amount<=0||amount>financial(o).balance||!['Transfer bank','Tunai','QRIS'].includes(r.method)||!r.reference.trim()||r.reference.length>150)return toast('Jumlah pembayaran melebihi sisa tagihan atau data tidak valid.');db.payments.unshift({...r,amount,orderId:id});audit('Pembayaran '+id+' '+money(amount));save();$('#modal').close();render();toast('Pembayaran dicatat sesuai saldo setelah kredit.')}
function renderDashboardV3(){const t=totals(),pending=db.orders.filter(o=>o.status==='Diproses'),unclassified=db.lots.filter(l=>l.product===null&&(l.kg>0||l.eggs>0)),expired=db.lots.filter(l=>l.expiresOn&&l.expiresOn<todayLocal()&&(l.kg>0||l.eggs>0)),days=Array.from({length:7},(_,i)=>addCalendarDays(selectedDate,i-6)),values=days.map(day=>db.production.filter(r=>r.date===day).reduce((s,r)=>s+r.eggs,0)),max=Math.max(1,...values),refundDue=db.orders.reduce((s,o)=>s+financial(o).refundDue,0);$('#app').innerHTML=title('Ringkasan peternakan','Dari hasil panen, batch, distribusi, hingga penyelesaian tagihan.',btn('+ Catat produksi',"openForm('production')"))+`<div class="datebar"><label>Tanggal produksi</label><input type="date" value="${selectedDate}" onchange="selectedDate=this.value||todayLocal();render()"></div><div class="stats">${stat('Produksi tanggal terpilih',num(t.eggs),'butir',num(t.kg)+' kg tercatat')}${stat('Stok fisik tersedia',num(t.stockPhysical),'kg','Termasuk karantina dan belum diklasifikasikan')}${stat('Stok batch siap jual',num(t.stock),'kg','Aktif, disetujui, dan belum lewat batas jual')}${stat('Pesanan diproses',pending.length,'pesanan','Hitung & timbang sebelum kurir berangkat')}</div>${unclassified.length?`<div class="setup-card"><strong>${unclassified.length} batch belum diklasifikasikan.</strong><p>Saldo lama tetap ada. Tentukan varian hasil pemeriksaan atau sortir menjadi beberapa batch sebelum pesanan baru.</p>${btn('Klasifikasikan saldo awal',"go('batches')",false)}</div>`:''}<div class="grid"><section class="card"><div class="cardhead"><h2>Produksi 7 hari</h2><span class="legend">Data catatan produksi</span></div><div class="chart">${values.map((v,i)=>`<div class="barcol"><div class="bar" style="height:${v/max*90}%;width:85%" title="${days[i]}: ${num(v)} butir"></div><label>${days[i].slice(8)}</label></div>`).join('')}</div><p class="note">${days[0]} sampai ${days[6]} · kolom kosong berarti belum ada produksi tercatat.</p></section><section class="card"><h2>Perlu ditindaklanjuti</h2><div class="item"><div class="dot">▧</div><div><strong>${expired.length} batch lewat batas jual</strong><p>Periksa status dan koreksi fisik di depo.</p><button class="textbtn" onclick="go('batches')">Lihat batch →</button></div></div><div class="item"><div class="dot">◇</div><div><strong>${db.cases.filter(c=>c.status!=='Ditutup').length} kasus belum ditutup</strong><p>Refund belum tercatat ${money(refundDue)}</p><button class="textbtn" onclick="go('cases')">Tindak lanjut →</button></div></div><div class="item"><div class="dot">▥</div><div><strong>Piutang bersih ${money(db.orders.reduce((s,o)=>s+financial(o).balance,0))}</strong><button class="textbtn" onclick="go('receivables')">Pantau jatuh tempo →</button></div></div></section></div><section class="card bottom"><div class="cardhead"><h2>Pesanan terbaru</h2><button class="textbtn" onclick="go('orders')">Semua pesanan →</button></div>${orderTable(db.orders.slice(0,5))}</section>`}
function renderFinanceV3(){const active=db.orders.filter(o=>o.status!=='Dibatalkan'),gross=active.reduce((s,o)=>s+o.total,0),credits=active.reduce((s,o)=>s+financial(o).credits,0),payments=db.payments.reduce((s,p)=>s+p.amount,0),refunds=db.refunds.reduce((s,r)=>s+r.amount,0);$('#app').innerHTML=title('Laporan usaha','Nilai pesanan, pembayaran, kredit, dan refund dicatat terpisah.',btn('↓ Ekspor pesanan','exportCSV()',false))+`<div class="stats">${stat('Nilai pesanan bruto',money(gross),'','Seluruh pesanan selain yang dibatalkan')}${stat('Nilai setelah kredit',money(gross-credits),'','Bruto dikurangi nota kredit')}${stat('Dana diterima bersih',money(payments-refunds),'','Pembayaran tercatat dikurangi refund')}${stat('Piutang bersih',money(active.reduce((s,o)=>s+financial(o).balance,0)),'','Setelah pembayaran dan kredit')}</div><section class="card bottom">${table(['KOMPONEN','NILAI'],[['Pembayaran diterima (bruto)',payments],['Nota kredit disetujui',credits],['Refund yang sudah dicatat',refunds],['Hak refund yang belum dicatat',active.reduce((s,o)=>s+financial(o).refundDue,0)],['Pembelian pakan tercatat',db.feed.reduce((s,r)=>s+r.cost,0)]].map(([label,value])=>`<tr><td>${label}</td><td>${money(value)}</td></tr>`))}</section><section class="card bottom"><h2 style="margin-bottom:15px">Pesanan per kategori pembeli</h2>${table(['KATEGORI','PESANAN','BRUTO','KREDIT','NILAI BERSIH'],['Perorangan','Wholesale','Hotel/Resort'].map(category=>{const rows=active.filter(o=>o.buyerCategory===category);return `<tr><td>${category}</td><td>${rows.length}</td><td>${money(rows.reduce((s,o)=>s+o.total,0))}</td><td>${money(rows.reduce((s,o)=>s+financial(o).credits,0))}</td><td>${money(rows.reduce((s,o)=>s+financial(o).netTotal,0))}</td></tr>`}))}</section><div class="notice">Nilai pesanan bukan pengakuan laba. Biaya dan estimasi HPP tersedia pada Biaya & HPP telur; pembayaran serta refund berasal dari catatan manual.</div>`}
function detail(id){const o=db.orders.find(o=>o.id===id);if(!o)return;const f=financial(o);$('#modal').innerHTML=`<h2>${esc(id)}</h2><p style="margin:15px 0"><strong>${esc(o.name)}</strong><br>${esc(o.address)}<br>PIC ${esc(o.contact||'—')} · ${esc(o.phone||'Belum tercatat')}</p><div class="notice">${esc(o.product)}<br>${esc(o.buyerCategory)} · ${esc(o.depot)}<br>Jadwal ${o.deliveryDate||'Belum diatur'} · ${esc(o.deliverySlot||'—')}<br>${esc(o.deliveryNotes||'')}<br>Nilai awal ${money(o.total)} · Kredit ${money(f.credits)}<br><strong>Tagihan bersih ${money(f.netTotal)} · Saldo ${money(f.balance)}</strong><br>Dana diterima bersih ${money(f.netPaid)} · Refund tertunda ${money(f.refundDue)}<br>Jatuh tempo ${o.paymentDueDate||'Belum ditetapkan'}</div>${tag(o.status)}${o.fulfillmentResult==='Dikembalikan'?'<span class="tag warn">Seluruh barang kembali ke depo</span>':''}<p class="note">Kurir: ${esc(o.courierName||'Belum ditugaskan')} ${esc(o.courierVehicle||'')}</p>${o.receipt?`<p>Diterima ${esc(o.receipt.recipient)} · ${new Date(o.receipt.time).toLocaleString('id-ID',{timeZone:'Asia/Bangkok'})}</p>`:''}<div class="actions">${btn('Tutup',"$('#modal').close()",false)}${btn('Invoice',`openInvoice('${id}')`,false)}${f.balance>0?btn('Pembayaran',`paymentForm('${id}')`,false):''}${o.status!=='Dibatalkan'?btn('Keluhan / retur',`caseForm('${id}')`,false):''}${o.status==='Diproses'?btn('Atur jadwal',`scheduleForm('${id}')`,false)+btn('Tugaskan kurir',`assignCourierForm('${id}')`,false)+btn('Hitung & timbang',`packingForm('${id}')`)+btn('Mulai pengiriman',`advance('${id}')`):''}${o.status==='Dalam pengiriman'?btn('Serah terima',`receiptForm('${id}')`)+btn('Kendala',`issueForm('${id}')`,false):''}${o.status==='Diproses'&&paid(id)===0?btn('Batalkan',`cancelForm('${id}')`,false):''}</div><h2 style="margin:20px 0 10px">Batch pesanan</h2>${table(['BATCH','VARIAN','KG / BUTIR','ASAL'],o.lotAllocations.map(a=>{const l=db.lots.find(l=>l.id===a.lotId);return `<tr><td><button class="textbtn" onclick="lotTrace('${l.id}')">${esc(l.code)}</button></td><td>${batchProductName(l.product)}</td><td>${num(a.kg)} / ${a.eggs}</td><td>${l.legacy?'Snapshot lama; asal belum ditelusuri':esc(l.source)}</td></tr>`}))}<div class="actions">${btn('Pesan lagi',`repeatOrder('${id}')`,false)}${o.buyerCategory!=='Perorangan'?btn('Jadikan template',`planForm('','${id}')`,false):''}${f.balance>0?btn('Atur jatuh tempo',`dueDateForm('${id}')`,false):''}</div>${o.paymentTermHistory.length?`<h2 style="margin:20px 0 10px">Riwayat jatuh tempo</h2>${table(['SEBELUM','SESUDAH','ALASAN'],o.paymentTermHistory.map(h=>`<tr><td>${h.previousDate||'Belum ditetapkan'}</td><td>${h.newDate||'Belum ditetapkan'}</td><td>${esc(h.reason)}</td></tr>`))}`:''}`;if(!$('#modal').open)$('#modal').showModal()}
function invoiceHTML(o){const f=financial(o),lines=batchOrderLines(o),credits=db.cases.filter(c=>c.orderId===o.id&&c.credit),refunds=db.refunds.filter(r=>r.orderId===o.id);return `<article class="invoice-paper"><div class="invoice-heading"><div><div class="brand"><span class="logo">∿</span>PamanKu</div><p>Peternakan & distribusi telur · Banten</p></div><div style="text-align:right"><h1>INVOICE</h1><strong>INV-${esc(o.id)}</strong><p>${o.createdAt?new Date(o.createdAt).toLocaleDateString('id-ID',{timeZone:'Asia/Bangkok'}):'Tanggal pesanan lama belum tercatat'}</p>${tag(o.status)}</div></div><div class="invoice-meta"><section><h2>${esc(o.name)}</h2><p>${esc(o.buyerCategory)}</p><p>${esc(o.address)}</p><p>PIC ${esc(o.contact||'—')} · ${esc(o.phone||'—')}</p></section><section><strong>${esc(o.depot)}</strong><p>Pengiriman ${o.deliveryDate||'Belum diatur'} · ${esc(o.deliverySlot||'—')}</p><p>Jatuh tempo ${o.paymentDueDate||'Belum ditetapkan'}</p><p>${esc(o.deliveryNotes||'')}</p></section></div>${table(['PRODUK','JUMLAH','SATUAN','HARGA / SATUAN','SUBTOTAL'],lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${num(l.quantity)}</td><td>${l.unit}</td><td>${money(l.unitPrice)}</td><td>${money(l.subtotal)}</td></tr>`))}<div class="invoice-summary"><div><span>Nilai awal pesanan</span><strong>${money(o.total)}</strong></div><div><span>Nota kredit</span><strong>− ${money(f.credits)}</strong></div><div><span>Ongkir demo</span><strong>Rp0</strong></div><div class="grand"><span>Tagihan bersih</span><strong>${money(f.netTotal)}</strong></div><div><span>Dana diterima</span><strong>${money(f.rawPaid)}</strong></div><div><span>Dana dikembalikan</span><strong>${money(f.refunds)}</strong></div><div class="grand"><span>Saldo tagihan</span><strong>${money(f.balance)}</strong></div>${f.refundDue>0?`<div><span>Refund belum tercatat</span><strong>${money(f.refundDue)}</strong></div>`:''}</div>${credits.length?`<h2>Nota kredit</h2>${table(['KASUS','ALASAN','JUMLAH'],credits.map(c=>`<tr><td>${c.id}</td><td>${esc(c.credit.reason)}</td><td>${money(c.credit.amount)}</td></tr>`))}`:''}${refunds.length?`<h2 style="margin-top:20px">Refund tercatat</h2>${table(['TANGGAL','REFERENSI','JUMLAH'],refunds.map(r=>`<tr><td>${r.date}</td><td>${esc(r.reference)}</td><td>${money(r.amount)}</td></tr>`))}`:''}<h2 style="margin:20px 0 10px">Batch pengiriman</h2>${table(['BATCH','VARIAN','BERAT','BUTIR'],o.lotAllocations.map(a=>{const l=db.lots.find(l=>l.id===a.lotId);return `<tr><td>${esc(l.code)}${l.legacy?' (arsip migrasi)':''}</td><td>${batchProductName(l.product)}</td><td>${num(a.kg)} kg</td><td>${a.eggs}</td></tr>`}))}<p style="margin-top:20px">Kurir ${esc(o.courierName||'Belum ditugaskan')} · ${o.fulfillmentResult==='Dikembalikan'?'Barang kembali ke depo':o.receipt?'Diterima '+esc(o.receipt.recipient):'Serah terima belum tercatat'}</p><p class="note">Pembayaran dan refund merupakan pencatatan manual. Arsip sebelum v3.0 tidak dianggap sebagai bukti asal panen.</p></article>`}
function renderGuide(){const sections=[['Pengaturan awal',[['Cadangkan data','Unduh cadangan sebelum koreksi besar. Aktifkan sinkronisasi dari perangkat yang memiliki catatan utama.','sync'],['Verifikasi depo','Ganti koordinat contoh dengan titik ruko/depo nyata, lalu tetapkan radius layanan.','inventory'],['Klasifikasikan saldo lama','Gunakan Klasifikasi atau Sortir sebagian; stok awal tidak hilang dan belum dijual sebagai varian tertentu.','batches']]],['Operasional peternakan',[['Catat hasil aktual','Catat telur baik, berat, telur rusak, pakan, dan mortalitas untuk tanggal kejadian.','production'],['Sortir & kualitas','Hasil panen menjadi batch belum diklasifikasikan. Tentukan varian, kondisi, tanggal panen yang diketahui, dan batas jual bila ditetapkan.','batches'],['Biaya & HPP','Masukkan harga pakan bertanggal dan biaya produksi. Biaya distribusi dilaporkan terpisah.','costs']]],['Pemesanan & pengiriman',[['Pelanggan & harga','Simpan PIC/alamat, kategori pembeli, termin, dan harga per kg/butir pada kategori pembeli.','customers'],['Pilih telur & depo','Pesan kg atau butir. Lokasi ponsel/koordinat membantu mencari depo dengan stok varian layak untuk tanggal kirim.','shop'],['Hitung, timbang, kirim','Periksa hasil fisik setiap batch, tugaskan kurir aktif di depo, lalu mulai antar dan catat penerima.','delivery']]],['Tagihan, keluhan & retur',[['Piutang & pembayaran','Saldo tagihan mengikuti pembayaran, nota kredit, dan refund tercatat; tanggal jatuh tempo disimpan per pesanan.','receivables'],['Retur fisik','Terima barang sekali per kasus, maksimal jumlah yang dikirim. Barang kembali masuk karantina.','cases'],['Kredit & refund','Tinjau nota kredit untuk koreksi tagihan. Catat refund hanya setelah dana benar-benar dikembalikan.','cases']]]];sections.push(['Laporan dan simulasi stok v3.3',[['Atur filter dan ekspor','Terapkan tanggal, depo, ambang kg dan rentang hari di Peringatan stok. Unduh CSV atau buka laporan cetak/PDF. Kekurangan adalah selisih ke ambang, bukan order pembelian.','alerts'],['Simulasikan pasokan','Pilih Semua depo untuk meninjau sumber surplus per varian. Simulasi menyisakan ambang di sumber, tidak memilih batch/rute, dan tidak memindahkan stok. Ekspor simulasi CSV untuk tindak lanjut manual.','alerts'],['Kandidat batch FEFO','Tinjau sumber batch dari batas jual terdekat, tanggal panen, lalu ID. Ekspor kandidat batch CSV atau lihat rincian pada PDF. Tidak mereservasi stok; timbang dan hitung butir sebelum transfer.','alerts'],['Transfer dari kandidat','Gunakan tanggal acuan hari ini. Siapkan transfer untuk mengisi batch, tujuan dan kg. Isi butir fisik serta catatan, lalu konfirmasikan. Perubahan saldo atau kondisi mengharuskan simulasi baru.','alerts'],['Baca snapshot laporan','Periksa cakupan dan waktu pembuatan UTC. Satu batch bisa muncul di beberapa kategori; jangan jumlahkan semua baris. Laporan bukan cadangan JSON.','alerts']]]);$('#app').innerHTML=title('Panduan PamanKu v5.0','Alur kerja dari panen hingga penutupan tagihan dan kasus pelanggan.')+`<div class="guide-grid">${sections.map(([title,steps])=>`<section class="card"><h2>${title}</h2>${steps.map(([heading,text,page],i)=>`<div class="guide-step"><b>${i+1}</b><div><strong>${heading}</strong><p>${text}</p><button class="textbtn" onclick="go('${page}')">Buka menu →</button></div></div>`).join('')}</section>`).join('')}</div><section class="card bottom"><h2>Ruang lingkup versi ini</h2><p style="margin-top:15px">Web responsif/PWA dengan penyimpanan server per akun ChatGPT dan salinan browser. Sinkronisasi lintas perangkat memakai akun yang sama. Data awal adalah contoh; akun pelanggan/kurir terpisah, payment gateway, notifikasi otomatis, dan paket APK/IPA belum diaktifkan.</p><p>Koordinat awal depo adalah contoh. Jarak rekomendasi adalah garis lurus. Batas jual dicatat oleh usaha; tidak dibuat otomatis. Laporan adalah catatan operasional, bukan laporan laba atau sertifikasi kualitas.</p><p>Pengujian perangkat fisik dan UAT operasional perlu dilakukan dengan data serta prosedur peternakan yang sebenarnya.</p></section>`}
function orderTable(rows){return table(['PELANGGAN / PESANAN','KATEGORI','DEPO','JUMLAH','TAGIHAN BERSIH','STATUS','AKSI'],rows.map(o=>`<tr><td><strong>${esc(o.name)}</strong><p>${esc(o.id)}</p></td><td>${esc(o.buyerCategory)}</td><td>${esc(o.depot)}</td><td>${esc(orderVolume(o))}</td><td>${money(financial(o).netTotal)}</td><td>${tag(o.status)}${o.fulfillmentResult==='Dikembalikan'?'<p>Diretur ke depo</p>':''}</td><td><button class="textbtn" onclick="detail('${o.id}')">Detail →</button></td></tr>`))}
menu.splice(menu.length-1,0,['alerts','!','Peringatan stok · v5.0']);
let stockAlertOptions={day:todayLocal(),minKg:20,horizon:3,depot:''};
const enhanceBeforeAlerts=enhance;
enhance=function(){enhanceBeforeAlerts();if(page==='alerts')renderStockAlerts();if(page==='dashboard')$('#app').insertAdjacentHTML?.('afterbegin',`<div class="setup-card"><strong>Pusat peringatan stok · v5.0</strong><p>Periksa stok menipis, batas jual, dan batch yang perlu ditinjau.</p>${btn('Buka peringatan',"go('alerts')",false)}</div>`)};
function applyStockAlertOptions(e){e.preventDefault();const v=Object.fromEntries(new FormData(e.target));try{if(!v.minKg.trim()||!v.horizon.trim())throw Error('Ambang dan hari wajib diisi.');const next={day:v.day,minKg:Number(v.minKg),horizon:Number(v.horizon),depot:v.depot};stockAlerts([],[],next.day,next.minKg,next.horizon);stockAlertOptions=next;render()}catch(err){toast(err.message)}}
function currentStockLots(){return db.lots.map(l=>({id:l.id,depot:l.depot,product:l.product,kg:l.kg,eggs:l.eggs,harvest:l.harvestDate||'',expiry:l.expiresOn||'',status:l.status,approved:l.approved}))}
function currentStockReport(){const o=stockAlertOptions;return stockAlerts(db.depots.filter(d=>!o.depot||d.name===o.depot).map(d=>d.name),currentStockLots(),o.day,o.minKg,o.horizon)}
function renderStockAlerts(){const o=stockAlertOptions,r=currentStockReport();$('#app').innerHTML=title('Peringatan stok · v5.0','Saldo bebas dan laporan untuk tindak lanjut pasokan.',`<div class="actions">${btn('Ekspor stok CSV','exportStockCsv()',false)}${btn('Laporan cetak / PDF','openStockReport()',false)}${btn('Simulasi CSV','exportTransferPlan()',false)}${btn('Periksa batch',"go('batches')")}</div>`)+`<section class="card"><form onsubmit="applyStockAlertOptions(event)"><div class="formrow"><div><label>Tanggal acuan</label><input name="day" type="date" required value="${o.day}"></div><div><label>Depo</label><select name="depot"><option value="">Semua depo</option>${db.depots.map(d=>`<option ${o.depot===d.name?'selected':''} value="${esc(d.name)}">${esc(d.name)}</option>`).join('')}</select></div><div><label>Ambang stok kg</label><input name="minKg" type="number" min="0" max="1000000" step="any" required value="${o.minKg}"></div><div><label>Rentang hari</label><input name="horizon" type="number" min="0" max="365" step="1" required value="${o.horizon}"></div></div><button class="btn primary">Terapkan filter</button></form><p class="note">Ekspor mengikuti filter yang sudah diterapkan. Kekurangan adalah selisih ke ambang kg, bukan order pembelian. Filter berlaku selama sesi ini. Saldo sesudah alokasi pesanan; tanggal acuan bukan rekonstruksi historis. Peringatan tidak mengubah kualitas atau mengirim notifikasi otomatis.</p></section><div class="stats">${stat('Stok menipis',r.low.length,'varian depo','Di bawah '+num(o.minKg)+' kg')}${stat('Mendekati batas jual',r.expiring.length,'batch','Sampai '+r.end+' inklusif')}${stat('Perlu tinjauan',r.review.length,'batch','Periksa alasan dan kondisi fisik')}</div><section class="card"><h2>Stok menipis</h2>${table(['DEPO','VARIAN','KG BEBAS LAYAK','BUTIR','KURANG KE AMBANG KG'],r.low.map(b=>`<tr><td>${esc(b.depot)}</td><td>${batchProductName(b.product)}</td><td>${num(b.kg)}</td><td>${num(b.eggs)}</td><td>${num(shortageKg(b.kg,o.minKg))}</td></tr>`))}</section><section class="card bottom">${transferPlanHtml(r,id=>id)}${batchTransferHtml(r,currentStockLots(),id=>id,stockLotLabel)}${btn('Kandidat batch CSV','exportBatchPlan()',false)}${btn('Buka batch untuk transfer fisik',"go('batches')",false)}${btn('Ekspor simulasi CSV','exportTransferPlan()',false)}</section><section class="card bottom"><h2>Mendekati batas jual</h2>${table(['BATCH','DEPO / VARIAN','BATAS JUAL','SALDO BEBAS'],r.expiring.map(l=>`<tr><td>${esc(db.lots.find(x=>x.id===l.id)?.code||l.id)}</td><td>${esc(l.depot)} / ${batchProductName(l.product)}</td><td>${l.expiry}</td><td>${num(l.kg)} kg / ${num(l.eggs)} butir</td></tr>`))}</section><section class="card bottom"><h2>Perlu tinjauan</h2>${table(['BATCH','DEPO / VARIAN','ALASAN','SALDO BEBAS'],r.review.map(({lot:l,reasons})=>`<tr><td>${esc(db.lots.find(x=>x.id===l.id)?.code||l.id)}</td><td>${esc(l.depot)} / ${batchProductName(l.product)}</td><td>${esc(reasons.join(' · '))}</td><td>${num(l.kg)} kg / ${num(l.eggs)} butir</td></tr>`))}</section>`}

function exportBatchPlan(){const report=currentStockReport(),csv=batchTransferCsv(report,currentStockLots(),id=>id,stockLotLabel,reportScope(),new Date().toISOString()),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='PamanKu-Batch-'+report.day+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Unduhan kandidat batch dimulai. Tidak ada reservasi atau perubahan stok.')}
function exportTransferPlan(){const report=currentStockReport(),csv=transferPlanCsv(report,id=>id,reportScope(),new Date().toISOString()),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='PamanKu-Simulasi-'+report.day+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Unduhan simulasi dimulai. Tidak ada perubahan stok atau order pembelian.')}
function reportScope(){return stockAlertOptions.depot||'Semua depo'}
function stockLotLabel(id){return db.lots.find(l=>l.id===id)?.code||id}
function exportStockCsv(){const report=currentStockReport(),csv=stockReportCsv(report,id=>id,stockLotLabel,reportScope(),new Date().toISOString()),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='PamanKu-Stok-'+report.day+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Unduhan laporan stok dimulai. Laporan bukan cadangan pemulihan data.')}
function openStockReport(){const report=currentStockReport(),html=stockReportHtml(report,id=>id,stockLotLabel,reportScope(),new Date().toISOString(),currentStockLots()),overlay=$('#invoice');overlay.innerHTML=`<div class="invoice-tools"><button class="btn" onclick="closeInvoice()">Tutup laporan</button><button id="printStockButton" class="btn primary" disabled onclick="printStockReport()">Cetak / Simpan PDF</button></div><iframe id="stockReportFrame" title="Laporan stok PamanKu" style="width:100%;height:78vh;border:0;background:white" onload="document.querySelector('#printStockButton').disabled=false"></iframe>`;overlay.hidden=false;$('#stockReportFrame').srcdoc=html}
function printStockReport(){const frame=$('#stockReportFrame');if(frame?.contentWindow){frame.contentWindow.focus();frame.contentWindow.print()}}

let candidateTransferDraft=null,shownBatchCandidates=[];
const renderStockAlertsBeforeCandidate=renderStockAlerts;
renderStockAlerts=function(){renderStockAlertsBeforeCandidate();const r=currentStockReport();shownBatchCandidates=batchTransferPlan(r,currentStockLots()).allocations;const actions=document.createElement('section');actions.className='card bottom';actions.innerHTML=`<h2>Transfer dari kandidat · v5.0</h2><p>Gunakan tanggal acuan hari ini. Usulan kg dan tujuan akan terisi; hitung butir fisik dan isi catatan sebelum konfirmasi. Saldo yang berubah memerlukan simulasi baru.</p>${table(['BATCH','SUMBER → TUJUAN','USULAN KG','AKSI'],shownBatchCandidates.map((a,i)=>`<tr><td>${esc(stockLotLabel(a.lotId))}</td><td>${esc(a.from)} → ${esc(a.to)}</td><td>${num(a.kg)}</td><td><button class="btn" ${r.day!==todayLocal()?'disabled':''} onclick="openCandidateTransfer(${i})">Siapkan transfer</button></td></tr>`))}`;$('#app').append(actions)};
function openCandidateTransfer(index){try{const choice=shownBatchCandidates[index];if(!choice)throw Error('Kandidat tidak tersedia. Buat ulang simulasi.');const report=currentStockReport(),lots=currentStockLots(),draft=prepareCandidateTransfer(report,lots,choice,todayLocal());assertCandidateCurrent(draft,currentStockLots(),todayLocal());candidateTransferDraft=draft;$('#modal').innerHTML=`<h2>Transfer dari kandidat batch</h2><p>${esc(stockLotLabel(choice.lotId))} · ${esc(choice.from)} → ${esc(choice.to)}</p><div class="notice">Periksa fisik. Maksimal ${num(choice.kg)} kg sesuai kandidat. Tujuan dan batch tetap. Butir wajib diisi dari hasil hitung. Batal tidak mengubah stok.</div><form onsubmit="submitCandidateTransfer(event)"><input type="hidden" name="lotId" value="${esc(choice.lotId)}"><input type="hidden" name="to" value="${esc(choice.to)}">${field('Berat fisik transfer kg','kg','number',`min="0.000001" max="${choice.kg}" step="0.000001" value="${choice.kg}"`)}${field('Butir fisik hasil hitung','eggs','number','min="1" step="1"')}${field('Catatan pemeriksaan dan serah terima','note','text','maxlength="300"')}<div class="actions"><button type="button" class="btn" onclick="cancelCandidateTransfer()">Batal</button><button class="btn primary">Konfirmasi transfer fisik</button></div></form>`;$('#modal').oncancel=()=>{candidateTransferDraft=null};if(!$('#modal').open)$('#modal').showModal()}catch(err){candidateTransferDraft=null;toast(err.message)}}
function cancelCandidateTransfer(){candidateTransferDraft=null;$('#modal').close()}
function submitCandidateTransfer(e){e.preventDefault();if(!candidateTransferDraft)return toast('Kandidat sudah ditutup atau dipakai. Buat ulang simulasi.');try{const r=Object.fromEntries(new FormData(e.target));validateCandidateTransfer(candidateTransferDraft,currentStockLots(),todayLocal(),{lotId:r.lotId,to:r.to,kg:Number(r.kg),eggs:Number(r.eggs),note:r.note});candidateTransferDraft=null;return transferLot(e)}catch(err){toast(err.message)}}
render();

function currentTraceLots(){return db.lots.map(l=>({id:l.id,parentId:l.parentId,depot:l.depot,product:l.product,kg:l.kg,eggs:l.eggs,status:l.status,harvest:l.harvestDate||'',expiry:l.expiresOn||''}))}
const lotTraceBefore36=lotTrace;
lotTrace=function(id){try{const t=traceBatch(currentTraceLots(),id);lotTraceBefore36(id);$('#modal').insertAdjacentHTML('beforeend',`<h2>Rantai asal & cabang · v5.0</h2><p>${t.ancestors.map(l=>esc(l.id)).join(' → ')}</p><div class="notice">Saldo bebas saat ini, bukan jumlah transfer awal atau bukti asal panen. Seluruh keluarga lintas depo dan varian, termasuk batch kosong. ${t.family.length} batch · ${num(t.kg)} kg / ${num(t.eggs)} butir bebas.</div>${table(['ID BATCH / INDUK','TINGKAT','DEPO / VARIAN','KUALITAS','KG / BUTIR BEBAS','PANEN / BATAS'],t.family.map(l=>`<tr><td>${l.id===id?'● ':''}${esc(l.id)}<p>${esc(l.parentId||'Akar')}</p></td><td>${l.depth}</td><td>${esc(l.depot)} / ${batchProductName(l.product)}</td><td>${esc(l.status)}</td><td>${num(l.kg)} / ${num(l.eggs)}</td><td>${esc(l.harvest||'Belum diketahui')} / ${esc(l.expiry||'Belum diatur')}</td></tr>`))}${btn('Ekspor telusur CSV',`exportTraceCsv('${id}')`,false)}`)}catch(e){toast(e.message)}};
function exportTraceCsv(id){try{const csv=traceBatchCsv(traceBatch(currentTraceLots(),id),id=>id,new Date().toISOString()),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='PamanKu-Telusur-'+Date.now()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message)}}

const renderGuideBefore36=renderGuide;renderGuide=function(){renderGuideBefore36();$('#app').insertAdjacentHTML('beforeend','<section class="card"><h2>Telusur asal & cabang · v5.0</h2><p>Buka Batch & varian → Telusuri. Periksa rantai akar sampai batch terpilih dan seluruh keluarga lintas depo, termasuk batch kosong. Ekspor telusur CSV menyimpan saldo saat ekspor. Induk dapat berasal dari transfer, sortir atau retur; hubungan batch bukan bukti asal panen. Saldo bebas saat ini bukan jumlah transfer awal. Penelusuran tidak mengubah stok.</p></section>')};

let traceOrderContext=null;
const lotTraceBefore37=lotTrace;
lotTrace=function(id){traceOrderContext=null;try{traceBatch(currentTraceLots(),id);lotTraceBefore37(id);traceOrderContext={id,scope:'family',status:'all',page:1,pageSize:20,back:null,filters:{category:'',from:'',to:'',query:''}};$('#modal').insertAdjacentHTML('beforeend','<section id="traceOrdersPanel"></section>');renderTraceOrdersPanel()}catch(e){toast(e.message)}};
function currentTraceOrders(filters=traceOrderContext?.filters,status=traceOrderContext?.status,scope=traceOrderContext?.scope){const c=traceOrderContext;if(!c)throw Error('Buka telusur batch terlebih dahulu.');return traceOrders(traceBatch(currentTraceLots(),c.id),db.orders.map(o=>({id:o.id,name:o.name,category:o.buyerCategory||'Perorangan',status:o.status,date:o.deliveryDate||'',depot:o.depot,allocations:o.lotAllocations})),scope,status,filters)}
function applyTraceOrderFilter(key,value){if(!traceOrderContext||!((key==='scope'&&['batch','family'].includes(value))||(key==='status'&&['all','notCancelled','Diproses','Dalam pengiriman','Selesai','Dibatalkan'].includes(value))))return;traceOrderContext.back=null;traceOrderContext[key]=value;traceOrderContext.page=1;renderTraceOrdersPanel()}
function renderTraceOrdersPanel(){try{const r=currentTraceOrders(),summary=traceOrdersSummary(r),visible=traceOrderPagination(r,traceOrderContext.page||1,traceOrderContext.pageSize??20);traceOrderContext.page=visible.page;$('#traceOrdersPanel').innerHTML=`<h2>Pesanan terkait batch · v5.0</h2>${traceSavedFiltersPanel()}<h3>Pilihan cepat pekerjaan harian</h3><div class="actions"><button class="btn" onclick="applyQuickTraceOrders('processingToday')">Diproses hari ini</button><button class="btn" onclick="applyQuickTraceOrders('shippingToday')">Dalam pengiriman hari ini</button><button class="btn" onclick="applyQuickTraceOrders('overdueProcessing')">Diproses lewat tanggal</button></div><p class="note">Tanggal perangkat saat tombol ditekan. Cakupan, depo dan urutan dipertahankan; pencarian dan kategori dikosongkan. Lewat tanggal = masih Diproses dengan tanggal kirim sebelum hari ini, tanpa menilai slot jam. Tanggal kosong dikecualikan. Filter tidak bergeser otomatis saat hari berganti; tekan ulang untuk hari terbaru.</p><div class="filters"><label>Cakupan<select onchange="applyTraceOrderFilter('scope',this.value)"><option value="family" ${r.scope==='family'?'selected':''}>Seluruh keluarga</option><option value="batch" ${r.scope==='batch'?'selected':''}>Batch ini saja</option></select></label><label>Status<select onchange="applyTraceOrderFilter('status',this.value)"><option value="all" ${r.status==='all'?'selected':''}>Semua status</option><option value="notCancelled" ${r.status==='notCancelled'?'selected':''}>Tanpa dibatalkan</option>${['Diproses','Dalam pengiriman','Selesai','Dibatalkan'].map(value=>`<option value="${value}" ${r.status===value?'selected':''}>${value}</option>`).join('')}</select></label></div><form onsubmit="applyTraceOrderDetails(event)"><label>Nomor pesanan / nama pelanggan (opsional, maks. 100 karakter)</label><input name="query" type="search" value="${esc(r.filters.query||'')}" placeholder="Cari nomor pesanan atau nama pelanggan"><div class="formrow"><div><label>Depo pesanan</label><select name="depot"><option value="">Semua depo pesanan</option>${db.depots.map(d=>`<option value="${esc(d.name)}" ${r.filters.depot===d.name?'selected':''}>${esc(d.name)}</option>`).join('')}</select></div><div><label>Urutan daftar</label><select name="sort">${['dateAsc','dateDesc','nameAsc','idAsc'].map(value=>`<option value="${value}" ${(r.filters.sort||'dateAsc')===value?'selected':''}>${traceOrderSortLabel(value)}</option>`).join('')}</select></div><div><label>Kategori pembeli</label><select name="category">${['','Perorangan','Wholesale','Hotel/Resort'].map(c=>`<option value="${esc(c)}" ${r.filters.category===c?'selected':''}>${esc(c||'Semua kategori')}</option>`).join('')}</select></div><div><label>Tanggal kirim mulai (opsional)</label><input name="from" type="date" value="${esc(r.filters.from)}"></div><div><label>Tanggal kirim sampai (opsional)</label><input name="to" type="date" value="${esc(r.filters.to)}"></div></div><button class="btn primary">Terapkan pencarian & filter</button><button type="button" class="btn" onclick="resetTraceOrderDetails()">Reset pencarian, kategori & tanggal</button><button type="button" class="btn" onclick="resetAllTraceOrderFilters()">Reset seluruh filter</button></form><p>Depo pesanan: ${esc(r.filters.depot||'Semua depo pesanan')} · Urutan: ${traceOrderSortLabel(r.filters.sort)}.</p><p>Pencarian diterapkan: ${esc(r.filters.query||'Tanpa pencarian')}.</p><p>Filter diterapkan: ${esc(r.filters.category||'Semua kategori')} · ${esc(r.filters.from||'Tanpa batas awal')} s.d. ${esc(r.filters.to||'Tanpa batas akhir')} (inklusif).</p><p class="notice">Rentang aktif mengecualikan pesanan tanpa tanggal kirim valid. Alokasi tercatat yang cocok, bukan jumlah terkirim atau saldo stok. Pesanan batal dapat tetap memiliki referensi; retur tidak dikurangkan. Ini membantu pemeriksaan, bukan daftar recall terverifikasi.</p><p>${r.count} pesanan · ${r.cancelled} dibatalkan · ${summary.batchCount} ID batch cocok</p><h3>Ringkasan pesanan · klik untuk menyaring</h3><button class="btn" ${traceOrderContext.back?'':'disabled'} onclick="undoTraceDrill()">Kembali sebelum klik ringkasan</button><p class="note">Memulihkan filter dan halaman sebelum klik terakhir, memakai data terkini. Halaman disesuaikan bila hasil berkurang. Hanya satu langkah; filter manual, pilihan cepat, reset atau membuka telusur ulang menghapus riwayat.</p><p class="note">Angka dari seluruh hasil filter saat ini. Klik kategori, status atau depo untuk mengganti satu filter dan kembali ke halaman pertama; filter lain tetap. Angka nol bisa dipilih. Tombol ini tidak mengubah status pesanan.</p>${traceSummaryButtons('Kategori pembeli','category',summary.categories,r.filters.category||'', 'Semua kategori')}${traceSummaryButtons('Status pesanan','status',summary.statuses,r.status,'Semua status')}${traceSummaryButtons('Depo pesanan','depot',summary.depots,r.filters.depot||'','Semua depo pesanan')}${r.count?table(['PESANAN / PELANGGAN','KATEGORI / STATUS','TANGGAL / DEPO','ID BATCH COCOK','ALOKASI COCOK'],visible.rows.map(o=>`<tr><td><button class="textbtn" onclick="detail('${o.id}')">${esc(o.id)}</button><p>${esc(o.name)}</p></td><td>${esc(o.category)} / ${esc(o.status)}</td><td>${esc(o.date||'Belum diatur')} / ${esc(o.depot)}</td><td>${o.lotIds.map(esc).join('; ')}</td><td>${num(o.kg)} kg / ${num(o.eggs)} butir</td></tr>`)):'<p>Tidak ada pesanan dengan referensi alokasi yang cocok.</p>'}<p>Menampilkan ${visible.start}–${visible.end} dari ${visible.count} pesanan · halaman ${visible.page}/${visible.pages}</p><div class="actions"><button class="btn" ${visible.page===1?'disabled':''} onclick="changeTraceOrdersPage(1)">Halaman pertama</button><button class="btn" ${visible.page===1?'disabled':''} onclick="changeTraceOrdersPage(${visible.page-1})">Sebelumnya</button><button class="btn" ${visible.page===visible.pages?'disabled':''} onclick="changeTraceOrdersPage(${visible.page+1})">Berikutnya</button><button class="btn" ${visible.page===visible.pages?'disabled':''} onclick="changeTraceOrdersPage(${visible.pages})">Halaman terakhir</button></div><div class="filters"><label>Pesanan per halaman<select onchange="changeTraceOrderPageSize(Number(this.value))">${[10,20,50].map(size=>`<option value="${size}" ${size===visible.pageSize?'selected':''}>${size}</option>`).join('')}</select></label><form onsubmit="applyTraceOrderJump(event)"><label>Ke halaman (1–${visible.pages})</label><input name="page" type="text" inputmode="numeric" pattern="[0-9]+" required value="${visible.page}"><button class="btn">Buka halaman</button></form></div><p class="note">${visible.pageSize} pesanan per halaman. Ringkasan, CSV dan PDF mencakup seluruh hasil filter, termasuk halaman lain.</p>${btn('Ekspor pesanan batch CSV','exportTraceOrdersCsv()',false)}${btn('Ekspor ringkasan CSV','exportTraceOrdersSummaryCsv()',false)}${btn('Laporan pesanan cetak / PDF','openTraceOrdersReport()',false)}`;}catch(e){toast(e.message)}}
function exportTraceOrdersCsv(){try{const csv=traceOrdersCsv(currentTraceOrders(),id=>id,new Date().toISOString()),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='PamanKu-Pesanan-Batch-'+Date.now()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message)}}
const renderGuideBefore37=renderGuide;renderGuide=function(){renderGuideBefore37();$('#app').insertAdjacentHTML('beforeend','<section class="card"><h2>Pesanan terkait batch · v5.0</h2><p>Batch & varian → Telusuri → Pesanan terkait batch. Pilih batch ini saja atau seluruh keluarga; filter semua status atau tanpa dibatalkan. Klik nomor pesanan untuk detail, atau Ekspor pesanan batch CSV. Jumlah merupakan alokasi cocok, bukan jumlah terkirim. Pesanan tanpa referensi batch tidak ditemukan. Ekspor memakai snapshot saat tombol ditekan; tidak mengubah stok, status atau mengirim pesan.</p></section>')};

function openTraceOrdersReport(){try{const report=currentTraceOrders(),html=traceOrdersHtml(report,id=>id,new Date().toISOString()),overlay=$('#invoice');$('#modal').close();overlay.innerHTML=`<div class="invoice-tools"><button class="btn" onclick="closeTraceOrdersReport()">Kembali ke telusur</button><button id="printTraceOrdersButton" class="btn primary" disabled onclick="printTraceOrdersReport()">Cetak / Simpan PDF</button></div><iframe id="traceOrdersReportFrame" title="Laporan pesanan terkait batch PamanKu" sandbox="allow-same-origin allow-modals" style="width:100%;height:78vh;border:0;background:white" onload="document.querySelector('#printTraceOrdersButton').disabled=false"></iframe>`;overlay.hidden=false;$('#traceOrdersReportFrame').srcdoc=html}catch(e){toast(e.message)}}
function printTraceOrdersReport(){const frame=$('#traceOrdersReportFrame');if(!$('#invoice').hidden&&frame?.contentWindow){frame.contentWindow.focus();frame.contentWindow.print()}}
function closeTraceOrdersReport(){closeInvoice();if(traceOrderContext){renderTraceOrdersPanel();if(!$('#modal').open)$('#modal').showModal()}}
const renderGuideBefore38=renderGuide;renderGuide=function(){renderGuideBefore38();$('#app').insertAdjacentHTML('beforeend','<section class="card"><h2>Laporan pesanan batch PDF · v5.0</h2><p>Batch & varian → Telusuri → Pesanan terkait batch. Pilih cakupan dan status, lalu Laporan pesanan cetak / PDF. Preview menyimpan snapshot saat laporan dibuka. Tekan Cetak / Simpan PDF setelah preview siap. Kembali ke telusur mempertahankan filter dan memperbarui daftar. Ringkasan kategori dan status menghitung pesanan yang sama, jangan dijumlahkan antar kelompok. Laporan tidak mengubah data atau menjalankan recall.</p></section>')};

function applyTraceOrderDetails(e){e.preventDefault();try{if(!traceOrderContext)throw Error('Buka telusur batch terlebih dahulu.');const v=Object.fromEntries(new FormData(e.target)),next=validateTraceOrderFilters({category:v.category,from:(v.from||'').trim(),to:(v.to||'').trim(),query:v.query||'',depot:v.depot||'',sort:v.sort||'dateAsc'});if(next.depot&&!db.depots.some(d=>d.name===next.depot))throw Error('Depo pesanan tidak ditemukan.');currentTraceOrders(next);traceOrderContext.back=null;traceOrderContext.filters=next;traceOrderContext.page=1;renderTraceOrdersPanel()}catch(e){toast(e.message)}}
function resetTraceOrderDetails(){if(traceOrderContext){traceOrderContext.back=null;traceOrderContext.filters={...traceOrderContext.filters,category:'',from:'',to:'',query:''};traceOrderContext.page=1;renderTraceOrdersPanel()}}
const renderGuideBefore39=renderGuide;renderGuide=function(){renderGuideBefore39();$('#app').insertAdjacentHTML('beforeend','<section class="card"><h2>Filter kategori & tanggal kirim · v5.0</h2><p>Pada pesanan terkait batch, pilih kategori dan tanggal kirim mulai/sampai, lalu Terapkan kategori & tanggal. Tanggal bersifat inklusif; satu batas boleh kosong. Rentang aktif mengecualikan pesanan tanpa tanggal valid. Daftar, ringkasan, CSV dan PDF mengikuti filter yang diterapkan. Perubahan kolom yang belum diterapkan tidak memengaruhi ekspor. Reset kategori & tanggal mempertahankan cakupan dan status. Membuka telusur kembali mereset filter; tidak ada perubahan stok atau status.</p></section>')};

function changeTraceOrdersPage(page){try{if(!traceOrderContext)return;const visible=traceOrderPagination(currentTraceOrders(),page,traceOrderContext.pageSize??20);traceOrderContext.page=visible.page;renderTraceOrdersPanel()}catch(e){toast(e.message)}}
const renderGuideBefore40=renderGuide;renderGuide=function(){renderGuideBefore40();$('#app').insertAdjacentHTML('beforeend','<section class="card"><h2>Pencarian & halaman · v5.0</h2><p>Di pesanan terkait batch, cari sebagian nomor pesanan atau nama pelanggan (maks. 100 karakter), lalu Terapkan pencarian & filter. Huruf kapital dan spasi disamakan; pencarian berupa teks biasa. Pencarian digabungkan dengan kategori/tanggal/cakupan/status. Daftar 20 pesanan per halaman, dengan Sebelumnya/Berikutnya. Ringkasan, CSV dan PDF mencakup semua hasil filter. Mengubah filter kembali ke halaman pertama. Perubahan kolom yang belum diterapkan tidak mengubah laporan. Tidak mengubah stok/status atau mengirim pesan.</p></section>')};

function resetAllTraceOrderFilters(){if(traceOrderContext){Object.assign(traceOrderContext,{scope:'family',status:'all',page:1,pageSize:20,back:null,filters:{category:'',from:'',to:'',query:'',depot:'',sort:'dateAsc'}});renderTraceOrdersPanel()}}
function exportTraceOrdersSummaryCsv(){try{const csv=traceOrdersSummaryCsv(currentTraceOrders(),id=>id,new Date().toISOString()),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='PamanKu-Ringkasan-Batch-'+Date.now()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message)}}
const renderGuideBefore45=renderGuide;renderGuide=function(){renderGuideBefore45();$('#app').insertAdjacentHTML('beforeend','<section class="card"><h2>Pemeriksaan operasional · v5.0</h2><p>Pada pesanan terkait batch, pilih status spesifik, depo pesanan dan urutan daftar. Depo mengikuti catatan pesanan, bukan lokasi stok batch saat ini. Urutan tersedia: tanggal terlama/terbaru, nama A–Z dan nomor A–Z; ID menjadi pemecah urutan. Filter tambahan baru berlaku setelah Terapkan. Ringkasan depo dan Ekspor ringkasan CSV mencakup semua hasil filter. Kelompok kategori/status/depo menghitung pesanan yang sama; jangan dijumlahkan antar kelompok. Reset seluruh filter kembali ke default keluarga, semua status/depo, tanpa pencarian/tanggal, urutan tanggal terlama, halaman pertama. Tidak mengubah stok/status atau mengirim pesan.</p></section>')};

function applyQuickTraceOrders(choice){try{if(!traceOrderContext)throw Error('Buka telusur batch terlebih dahulu.');const quick=traceOrderQuickFilter(traceOrderContext.filters,choice,todayLocal());if(quick.filters.depot&&!db.depots.some(d=>d.name===quick.filters.depot))throw Error('Depo pesanan tidak ditemukan.');currentTraceOrders(quick.filters,quick.status);Object.assign(traceOrderContext,{status:quick.status,filters:quick.filters,page:1,back:null});renderTraceOrdersPanel();toast(quick.label+' · '+quick.asOf)}catch(e){toast(e.message)}}
const renderGuideBefore46=renderGuide;renderGuide=function(){renderGuideBefore46();$('#app').insertAdjacentHTML('beforeend','<section class="card"><h2>Pilihan cepat harian · v5.0</h2><p>Pada pesanan terkait batch, pilih Diproses hari ini, Dalam pengiriman hari ini atau Diproses lewat tanggal. Pilihan memakai tanggal perangkat saat tombol ditekan, mengosongkan pencarian/kategori, mempertahankan cakupan/depo/urutan, lalu kembali ke halaman pertama. Lewat tanggal berarti masih Diproses dengan tanggal kirim sebelum hari ini; tidak menilai slot jam. Tanggal kosong dikecualikan. Rentang tetap setelah diterapkan; tekan ulang setelah hari berganti. CSV/PDF menyimpan status dan tanggal yang diterapkan. Tidak mengubah stok/status atau mengirim pengingat.</p></section>')};

function traceSummaryButtons(title,dimension,rows,selected,allLabel){const allValue=dimension==='status'?'all':'';return `<h4>${esc(title)}</h4><div class="actions"><button class="btn" aria-pressed="${selected===allValue}" data-value="${allValue}" onclick="drillTraceOrders('${dimension}',this.dataset.value)">${selected===allValue?'✓ ':''}${esc(allLabel)}</button>${rows.map(x=>`<button class="btn" aria-pressed="${selected===x.label}" data-value="${esc(x.label)}" onclick="drillTraceOrders('${dimension}',this.dataset.value)">${selected===x.label?'✓ ':''}${esc(x.label)} · ${x.count}</button>`).join('')}</div>`}
function drillTraceOrders(dimension,value){try{if(!traceOrderContext)throw Error('Buka telusur batch terlebih dahulu.');const next=traceOrderDrilldown(traceOrderContext.filters,traceOrderContext.status,dimension,value);if(next.filters.depot&&!db.depots.some(d=>d.name===next.filters.depot))throw Error('Depo pesanan tidak ditemukan.');currentTraceOrders(next.filters,next.status);const c=traceOrderContext,back=traceOrderViewSnapshot({lotId:c.id,scope:c.scope,status:c.status,page:traceOrderPagination(currentTraceOrders(),c.page||1,c.pageSize??20).page,pageSize:c.pageSize??20,filters:c.filters});Object.assign(traceOrderContext,{status:next.status,filters:next.filters,page:1,back});renderTraceOrdersPanel()}catch(e){toast(e.message)}}
const renderGuideBefore47=renderGuide;renderGuide=function(){renderGuideBefore47();$('#app').insertAdjacentHTML('beforeend','<section class="card"><h2>Ringkasan interaktif · v5.0</h2><p>Klik kategori, status atau depo di ringkasan pesanan terkait batch untuk mengganti filter kelompok itu; nilai terpilih bertanda ✓. Semua kategori/Semua status/Semua depo pesanan hanya membuka kembali filter kelompok tersebut. Filter lain, cakupan dan urutan tetap; halaman kembali pertama. Angka dihitung dari seluruh hasil filter saat ini, dan angka nol bisa dipilih. Daftar, CSV dan PDF mengikuti filter baru. CSV/PDF tetap statis; tidak mengubah stok/status atau mengirim pesan.</p></section>')};

function undoTraceDrill(){try{const c=traceOrderContext;if(!c?.back)throw Error('Belum ada klik ringkasan yang bisa dikembalikan.');const previous=traceOrderViewSnapshot(c.back,c.id);if(previous.filters.depot&&!db.depots.some(d=>d.name===previous.filters.depot))throw Error('Depo pesanan pada riwayat tidak ditemukan.');const report=currentTraceOrders(previous.filters,previous.status,previous.scope),visible=traceOrderPagination(report,previous.page,previous.pageSize??20);Object.assign(c,{scope:previous.scope,status:previous.status,filters:previous.filters,page:visible.page,pageSize:visible.pageSize,back:null});renderTraceOrdersPanel()}catch(e){toast(e.message)}}
const renderGuideBefore48=renderGuide;renderGuide=function(){renderGuideBefore48();$('#app').insertAdjacentHTML('beforeend','<section class="card"><h2>Kembali sebelum klik ringkasan · v5.0</h2><p>Setelah klik kategori/status/depo atau tombol Semua pada ringkasan, tekan Kembali sebelum klik ringkasan. Filter lengkap dan halaman sebelum klik terakhir dipulihkan, dengan data terkini. Halaman disesuaikan bila hasil berkurang. Hanya satu langkah; setelah kembali riwayat habis. Filter manual, pilihan cepat, reset dan membuka telusur ulang menghapus riwayat. Riwayat hanya untuk sesi ini dan batch yang sama; tidak membatalkan transaksi atau mengubah stok/status.</p></section>')};

function changeTraceOrderPageSize(size){try{if(!traceOrderContext)return;const visible=traceOrderPagination(currentTraceOrders(),1,size);Object.assign(traceOrderContext,{pageSize:visible.pageSize,page:1});renderTraceOrdersPanel()}catch(e){toast(e.message)}}
function applyTraceOrderJump(e){e.preventDefault();try{if(!traceOrderContext)throw Error('Buka telusur batch terlebih dahulu.');const v=Object.fromEntries(new FormData(e.target)),visible=traceOrderPagination(currentTraceOrders(),v.page,traceOrderContext.pageSize??20);traceOrderContext.page=visible.page;renderTraceOrdersPanel()}catch(e){toast(e.message)}}
const renderGuideBefore49=renderGuide;renderGuide=function(){renderGuideBefore49();$('#app').insertAdjacentHTML('beforeend','<section class="card"><h2>Navigasi daftar · v5.0</h2><p>Pilih 10, 20 atau 50 pesanan per halaman; perubahan ukuran kembali ke halaman satu tanpa mengubah filter atau riwayat klik ringkasan. Gunakan Halaman pertama/terakhir atau isi nomor pada Ke halaman lalu Buka halaman. Nomor harus bilangan bulat positif; melebihi batas menuju halaman terakhir. Kembali sebelum klik ringkasan memulihkan nomor dan ukuran halaman. Ringkasan, CSV dan PDF mencakup semua hasil filter. Reset seluruh filter dan telusur ulang kembali ke 20 baris. Tidak mengubah transaksi.</p></section>')};

function traceSavedStorageKey(){return 'telurfarm-trace-saved-v1-'+(cloudEnabled&&cloudUser?'account-'+cloudUser:'device')}
function readTraceSavedFilters(){const raw=localStorage.getItem(traceSavedStorageKey());if(raw===null)return emptyTraceSavedFilters();if(raw.length>50000)throw Error('Daftar filter tersimpan terlalu besar.');return validateTraceSavedFilters(JSON.parse(raw))}
function writeTraceSavedFilters(value){const next=validateTraceSavedFilters(value);localStorage.setItem(traceSavedStorageKey(),JSON.stringify(next));return next}
function traceSavedFiltersPanel(){try{const store=readTraceSavedFilters(),entries=store.items.filter(x=>x.view.lotId===traceOrderContext.id);return `<section class="card"><h3>Filter pemeriksaan tersimpan · v5.0</h3><p>Disimpan di browser untuk batch ini, terpisah dari transaksi; tanggal tetap. Maksimum 10 filter pada penyimpanan akun sinkron aktif atau perangkat saat tidak aktif. Tidak ikut cadangan/sinkronisasi transaksi.</p><form onsubmit="saveTraceFilter(event)"><label>Nama filter (maks. 60 karakter, unik per batch)</label><input name="name" required><button class="btn" ${store.items.length>=10?'disabled':''}>Simpan filter yang diterapkan</button></form><p>${entries.length} filter untuk batch ini · ${store.items.length}/10 tersimpan.</p>${entries.length?`<label>Filter tersimpan</label><select id="traceSavedPick">${entries.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><div class="actions"><button class="btn" onclick="applySavedTraceFilter($('#traceSavedPick').value)">Pakai filter</button><button class="btn" onclick="deleteSavedTraceFilter($('#traceSavedPick').value)">Hapus filter</button></div>`:'<p>Belum ada filter tersimpan untuk batch ini.</p>'}<details><summary>Kelola seluruh filter (${store.items.length})</summary>${store.items.map(x=>`<p>${esc(x.name)} · batch ${esc(x.view.lotId)} <button class="btn" data-id="${x.id}" onclick="deleteSavedTraceFilter(this.dataset.id)">Hapus filter</button></p>`).join('')}</details></section>`}catch(e){return '<p class="notice">Filter tersimpan tidak dapat dibaca: '+esc(e.message)+'. Transaksi tetap tersedia.</p>'}}
function saveTraceFilter(e){e.preventDefault();try{const c=traceOrderContext;if(!c)throw Error('Buka telusur batch terlebih dahulu.');const v=Object.fromEntries(new FormData(e.target));currentTraceOrders();const store=readTraceSavedFilters(),view=traceOrderViewSnapshot({lotId:c.id,scope:c.scope,status:c.status,page:1,pageSize:c.pageSize??20,filters:c.filters});writeTraceSavedFilters(addTraceSavedFilter(store,'VIEW-'+crypto.randomUUID(),v.name,view));renderTraceOrdersPanel();toast('Filter pemeriksaan tersimpan di browser.')}catch(e){toast('Filter gagal disimpan: '+e.message)}}
function applySavedTraceFilter(id){try{const c=traceOrderContext;if(!c)throw Error('Buka telusur batch terlebih dahulu.');const item=readTraceSavedFilters().items.find(x=>x.id===id);if(!item)throw Error('Filter tersimpan tidak ditemukan.');const view=traceOrderViewSnapshot(item.view,c.id);if(view.filters.depot&&!db.depots.some(d=>d.name===view.filters.depot))throw Error('Depo pada filter tidak ditemukan.');currentTraceOrders(view.filters,view.status,view.scope);Object.assign(c,{scope:view.scope,status:view.status,filters:view.filters,page:1,pageSize:view.pageSize??20,back:null});renderTraceOrdersPanel()}catch(e){toast('Filter tidak dapat dipakai: '+e.message)}}
function deleteSavedTraceFilter(id){try{const c=traceOrderContext,item=readTraceSavedFilters().items.find(x=>x.id===id);if(!c||!item)throw Error('Filter tersimpan tidak ditemukan.');writeTraceSavedFilters(removeTraceSavedFilter(readTraceSavedFilters(),id));renderTraceOrdersPanel();toast('Pengaturan filter dihapus. Transaksi tetap.')}catch(e){toast('Hapus filter gagal: '+e.message)}}
const renderGuideBefore50=renderGuide;renderGuide=function(){renderGuideBefore50();$('#app').insertAdjacentHTML('beforeend','<section class="card"><h2>Filter pemeriksaan tersimpan · v5.0</h2><p>Di pesanan terkait batch, simpan filter yang sudah diterapkan dengan nama unik per batch. Maksimum 10 pada penyimpanan browser untuk akun sinkron aktif, atau perangkat saat tidak aktif. Pakai filter memulihkan pengaturan dan ukuran halaman, mulai halaman pertama serta menghapus riwayat kembali, dengan data terkini. Tanggal tetap; bukan jadwal relatif. Hapus hanya menghapus pengaturan. Filter tidak ikut cadangan transaksi, tidak sinkron antarperangkat dan bisa hilang saat data browser dihapus.</p></section>')};

// Shared team operations have a separate authenticated server boundary.
const personalMenu=allMenus;allMenus=function(){personalMenu();$("#modal").insertAdjacentHTML("beforeend","<p><a href=\"team.html\">Ruang kerja tim dan RBAC v6.0 →</a></p>")};
const personalRender=render;render=function(){personalRender();$("#nav").insertAdjacentHTML("afterbegin","<a class=\"btn\" style=\"display:block;margin-bottom:12px\" href=\"team.html\">Tim dan akses v6.0 →</a>");if(page==="dashboard")$("#app").insertAdjacentHTML("afterbegin","<div class=\"setup-card\"><strong>PamanKu v6.0 · Ruang kerja tim</strong><p>Area ini adalah salinan pribadi v5.0. Data tim dan hak peran dikelola terpisah di server.</p><a class=\"btn\" href=\"team.html\">Buka ruang kerja tim</a></div>")};render();
